quests[64846] = { id = 64846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torghast", description = "In den Hallen Torghasts werden zahllose Seelen gequält. Sie brauchen Eure Hilfe!", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Zu viele haben wir schon in Torghast verloren. Hineinzukommen ist schwierig... aber nicht unmöglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[64849] = { id = 64849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turm der Verdammten", description = "Wir wissen nicht viel über Torghast. Schicksalsschreiber Roh-Tahl behauptet jedoch, dass es dort Dinge zu erledigen gibt.\n\nEr glaubt, dass wir einen Weg finden können, diesen Ort zu erreichen... und dass dort jemand Eure Hilfe braucht.\n\nTut alles Nötige, um Torghast zu erreichen, und helft denjenigen, die Ihr dort findet.", sourceObjective = "Begebt Euch nach Torghast, indem Ihr in den Ring der Übertragung springt, und sucht dort nach Wesen, die Eure Hilfe benötigen.", completion = "Bleibt weg!\n\nMoment... Ihr gehört nicht zu den Truppen des Kerkermeisters.\n\nKiste, wir haben Besuch! Zeit für die schöne Musik, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[64850] = { id = 64850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiken von Torghast", description = "Ich habe schon von Euch gehört, <Schlundgänger/Schlundgängerin>! Ihr kennt sicherlich auch mich, den legendären Ve'nish.\n\nIch bin hier, um mithilfe meiner Kiste fabelhafte Schätze in Torghast zu finden. Ich sehe schon, wie Ihr sie bewundert.\n\nVielleicht können wir uns zusammentun. Möchtet Ihr vorausgehen und Torghast schon einmal auskundschaften?\n\nIch gebe Euch sogar eine Belohnung, wenn Ihr dabei etwas entdeckt.", sourceObjective = "Helft bei Ve'nishs Erkundung von Torghast, indem Ihr dort einen Flügel abschließt. Nutzt den Wegfinder in Torghast, um in unterschiedliche Flügel zu gelangen.", completion = "Ach, hier wimmelt es von allerhand schrecklichen Kreaturen... und jeder Menge Macht!\n\nGroßartig! Hast du das gehört, Kiste? Wir werden hier alles Mögliche finden... vielleicht sogar mehr als diese feige Ve'nari draußen im Schlund.\n\nÄhm, ich danke Euch, Schlundgänger. Ihr habt Euren Teil gut erledigt. Ich werde später noch Fragen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64852] = { id = 64852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aeonmatrix", description = "<Firim kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand zu Firim.\n\nBereitgestellter Gegenstand:", completion = "Genau das habe ich gebraucht! Hier, das ist für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64853] = { id = 64853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Pfade, ein Weg", description = "Hat das Eure Frage beantwortet?\n\nOh, Ihr wolltet etwas, um der Herrschaftsmagie vollständig zu widerstehen? Dazu fällt mir leider nichts ein. Die Sprache der Ersten kann das Unvermeidliche nur hinauszögern.\n\nIch kann Euch allerdings sagen, wo Ihr noch komplexere Phrasen aus der Sprache der Ersten findet. Und zwar in den Gewölben der Endlosen Sande.\n\nIch wünschte, ich könnte selbst gehen, aber dort wimmelt es nur so von diesen elenden Schlundgebundenen.\n\nViel Glück bei Euren weiteren Studien!", sourceObjective = "Erstattet dem Primus in der Geometrischen Höhle Bericht.", completion = "Diese Älteste hat uns eine wichtige Antwort zu diesem Rätsel beschert. Aber nun heißt es Handeln. Und das wird nicht einfach.\n\nAls Erstes müssen wir den Helm mit den unverständlichen Phrasen der Ersten aus den Endlosen Sanden erfüllen.\n\nAber das allein reicht nicht. Wir brauchen noch mehr. Ich bereite alles vor, während Ihr besorgt, was wir benötigen. Ich melde mich anschließend bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[64854] = { id = 64854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallbei(l)spiele", description = "Die Wildtiere von Zereth Mortis werden wie magisch von der Schöpfungsenergie angezogen, die durch das Land fließt. Sobald die Tiere etwas finden, das mit dieser Energie aufgeladen ist... fressen sie es!\n\nDie schlundgebundenen Kryptoseher wissen das und suchen nach solchen Tieren, um die Reste der Energie zu ernten.\n\nBeseitigt alle Kryptoseher. Stellt dann mit der Eindämmungsfalle einige der Tiere ruhig und studiert sie für unsere Forschungen.", sourceObjective = "Tötet 5 schlundgebundene Kryptoseher und untersucht die aufgelisteten Tiere.", completion = "Diese Informationen werden uns helfen, die Mysterien von Zereth Mortis zu entschlüsseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[64860] = { id = 64860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ätherisches Gitter", description = "<Firim kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand zu Firim.\n\nBereitgestellter Gegenstand:", completion = "Genau das habe ich gebraucht! Hier, das ist für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64861] = { id = 64861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kismetrische Scheibe", description = "<Firim kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand zu Firim.\n\nBereitgestellter Gegenstand:", completion = "Genau das habe ich gebraucht! Hier, das ist für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64863] = { id = 64863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanwächter", description = "Die Konstrukte, welche durch den Hort patrouillieren, werden nicht durch die Magie des Erdwächters animiert.\n\n<Derwischians Blick verdüstert sich.>\n\nWir können keine Feinde in unseren Reihen dulden.\n\nVernichtet sie und räumt uns den Weg nach vorne frei.", sourceObjective = "Besiegt 4 Wächter oder Konstrukte.", completion = "Diese Konstrukte wurden durch die Magie des blauen Drachenschwarms belebt.\n\nDer Erdwächter hätte das nie zugelassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64864] = { id = 64864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwacht, Dracthyr", description = "<Ihr seht nur Erinnerungsfetzen vor Euch, während Ihr aus Eurem schier endlosen Schlaf erwacht.\n\nDer Dracthyr vor Euch reagiert nicht, so als wäre er durch eine unbekannte Macht festgefroren. Ihr spürt, dass Ihr die Macht besitzt, Euren Verbündeten zu befreien.\n\nMöglicherweise gibt es noch andere im Hort, die in solch einer Stasis gefangen sind.\n\nEs obliegt Euch, sie zu erwecken.>", sourceObjective = "Weckt die anderen Dracthyr.", completion = "<Azurathel hört sich Euren Bericht an.>\n\nMeine Erinnerungen sind genauso zerrüttet wie die Euren, {name}. Aber dafür bleibt jetzt keine Zeit.\n\nWir müssen die Situation einschätzen und einen Plan schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64865] = { id = 64865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrüsten", description = "Gegner sind eingedrungen, unsere Leute werden in einer magischen Stasis gehalten und unser Hort scheint zusammenzubrechen.\n\nDeshalb trainieren wir, {name}. Im Zweifelsfall greift auf das zurück, was Ihr wisst.\n\nAber das Wichtigste zuerst. Waffen, Rüstungen, Vorräte. Sammelt, was Ihr finden könnt, und rüstet Euch aus, während ich unsere Streitkräfte zusammenrufe.\n\nDann werden wir den Erdwächter ausfindig machen. Neltharion kann uns sicherlich die Antworten auf unsere Fragen geben.", sourceObjective = "Beschafft Waffen, Rüstungen und Vorräte.", progress = "Wenn Euer Gedächtnis Euch im Stich lässt, dann greift auf Euer Training zurück.", completion = "Diese Ausrüstung ist uralt und das Essen zu Staub zerfallen.\n\nDas ergibt keinen Sinn... Diese Rationen hätten eigentlich ein Leben lang halten sollen.\n\nNa ja, wir machen das Beste aus dem, was wir haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64866] = { id = 64866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kessel", description = "Eure Fertigkeiten werden gebraucht, <Rufer/Ruferin>.\n\nDer Hort zerfällt und wir sind knapp an Vorräten. Wir müssen den Durchgang nach draußen erreichen, aber zuerst müssen wir diese arkane Barriere überwinden.\n\nIn der Kammer dahinter befinden sich Dracthyr, welche Hilfe benötigen. Versorgt ihre Wunden. Vernichtet jegliche Gegner, die sich Euch in den Weg stellen.\n\nEs ist vielleicht das letzte Mal, dass wir gemeinsam durch diese Hallen gehen, {name}. Macht etwas daraus.", sourceObjective = "Bereitet Euch darauf vor, den Hort zu verlassen.", completion = "Ihr habt unsere Leute geheilt. Gut gemacht.\n\nNun müssen wir uns um den Drachen kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64867] = { id = 64867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Erleuchteten", description = "Ah, ja. Auf diesen Augenblick freue ich mich schon lange!\n\nKommt. Lasst uns diesen Erfolg teilen.\n\nIch habe etwas ganz Besonderes für Euch vorbereitet.", sourceObjective = "Sprecht mit Vilo in der Zuflucht in Zereth Mortis.", completion = "Eine ganz schön prächtige Belohnung. Seid Ihr sicher, dass Ihr das allein schafft?", sourceObjectiveStatus = "unverified-source-field" }
quests[64870] = { id = 64870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon der Erleuchteten Mittler", description = "Aber, aber. Ihr wart ziemlich geschäftig, nicht wahr?", sourceObjective = "Sprecht mit Vilo in der Zuflucht in Zereth Mortis.", sourceObjectiveStatus = "unverified-source-field" }
quests[64871] = { id = 64871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Drache auf der Schwelle", sourceObjective = "Besiegt Lapisagos und flieht aus dem Kriegshort.", completion = "Wir räumen den Schutt und das Geröll beiseite und stellen sicher, dass kein {race} zurückbleibt.\n\nDoch zuerst müssen wir das Gebiet sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64872] = { id = 64872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das innere Feuer", description = "Ihr seid <ein Rufer/eine Ruferin>, {name}, und gehört zu den Besten der Besten. Elitesoldaten wie Ihr haben die Fertigkeiten aller unserer Weyrns gemeistert.\n\nIch erwarte einiges von Euch.\n\nAuch wenn Eure Erinnerungen ausgelöscht wurden, fließt die Macht der Drachen durch Eure Venen. Nutzt sie.\n\nEine Eurer mächtigsten Waffen ist der Atemangriff. Das innere Feuer wird stärker, je länger Ihr einatmet.\n\nDie Insektenschwärme über unserem Übungsfeld sollten passende Ziele abgeben.", sourceObjective = "Erlernt 'Feueratem' und übt ermächtigte Angriffe.", progress = "Ein schöner, tiefer Atemzug macht den Kopf frei.", completion = "Gut. Ihr erinnert Euch an Euer Training.\n\nHaltet den Kopf unten und die Lungen voll Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64873] = { id = 64873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flügel ausbreiten", description = "Es ermutigt mich zu sehen, dass so viele dem Kriegshort entkommen sind. Mein eigener Weyrn... hatte nicht so viel Glück.\n\n<Glutthal steht einen Moment schweigend da.>\n\nEs gibt noch weitere Horte überall auf der Insel, voller Dracthyr in Gefahr. Es wird stärkere Flügel brauchen, um sie zu erreichen.\n\nKonzentriert Euch. Erinnert Euch an das, was Ihr gelernt habt. Bekommt wieder ein Gefühl für den Wind. Ihr müsst Eure Stärke wiedererlangen und zu den anderen Horten fliegen.\n\nDie Zeit für Ruhe ist vorüber.", sourceObjective = "Übt 'Segeln'.", completion = "Ihr kommt schneller dahinter als ich damals.\n\nAber Ihr habt ja auch die Ruferausbildung abgeschlossen. Ich dagegen habe versucht, mich als Diplomatin zu spezialisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64875] = { id = 64875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrlich wunderbar", description = "{name}, bin ich froh, dass Ihr da seid! Firim hat mich geschickt, um Euch zu suchen.\n\nEs geht um das Orakel... es ist... schwer zu beschreiben! Seht am besten selbst. Beeilt Euch!", sourceObjective = "Reist zur Höhle des Verbannten und seht selbst, was mit Saezurah geschieht.", progress = "Wir müssen uns beeilen, {name}. Wir haben keine Ahnung, wie lange das hält.", completion = "Wir stehen vielleicht kurz vor einer wundervollen Offenbarung!", sourceObjectiveStatus = "unverified-source-field" }
quests[64876] = { id = 64876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sphärenklänge", description = "Es fing langsam an und dann wurde die Energie, die von dem Orakel ausgeht, immer stärker, bis sich dieser wunderbare Entwurf herauskristallisierte, den Ihr vor Euch seht.\n\nDieser grauenhafte Lärm folgte kurz darauf.\n\nMeine Versuche, mich den Fraktalen zu nähern, waren... nicht von Erfolg gekrönt. Aber sie scheinen eine Resonanz in Pocopoc zu erzeugen.\n\nIhr teilt doch eine ganz besondere Verbindung, vielleicht habt Ihr mehr Glück als ich.", sourceObjective = "Untersucht die Fraktale um Saezurahs Körper.", completion = "Eine Vision! Das Orakel kommuniziert mit uns! Habt Ihr das auch gesehen? Welch eine Pracht! Mit so einer... gewaltigen Migräne im Anschluss.", sourceObjectiveStatus = "unverified-source-field" }
quests[64877] = { id = 64877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navigation Playtest: Level Up (PART 2)", description = "Genießt das Ende des Tieflands!" }
quests[64878] = { id = 64878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welch lange und seltsame Reise", description = "<Die Stimme aus der Vision spricht durch Pocopoc, allerdings klingt sie verzerrt und weit entfernt.>\n\nIch... bin Saezurah. Orakel. Dieses Automa... spricht mit meiner Stimme. Handelt durch meinen Willen. Im Moment.\n\nDas Muster... ist zerrissen. Gestört. Heilung ist nötig.\n\nEin Schwarm der Gier überfällt die Sande. Was er begehrt, darf nicht verschlungen werden.\n\nKommt mit mir. Folgt meiner Stimme.", sourceObjective = "Folgt Pocopoc, um Eure Vision zu verstehen.", progress = "Pocopoc hat das Ziel noch nicht erreicht.", completion = "Über den Sanden. Über uns. Das Gefäß wartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64879] = { id = 64879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine monumentale Entdeckung", description = "<Schlundgänger/Schlundgängerin>, Pelagos hat vorhin berichtet, die Vorbereitungen des Orakels wären abgeschlossen und Ihr würdet dringend gebraucht.\n\nWenn uns das bei unserer Aufgabe hier helfen kann, dann solltet Ihr unbedingt dabei sein. Geht zur Höhle des Verbannten und findet heraus, was sie brauchen.", sourceObjective = "Trefft Euch mit Firim in der Höhle des Verbannten.", completion = "Sterblicher, ich habe monumentale Neuigkeiten. Saezurah hat angedeutet, dass die Vorbereitungen abgeschlossen sind. Es wird Zeit, einen neuen Richter zu erschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64888] = { id = 64888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geliehene Macht", description = "Das Land gibt. Das Land dürstet. Eindringlinge verschlingen, was wir benötigen.\n\nHolt zurück, was bereits verschlungen. Absorbiert, was noch in Fülle vorhanden.\n\nSchwingen brauchen Wind zum Fliegen. Wir brauchen Energie für den Aufstieg.", sourceObjective = "Besiegt instabile angelockte Feinde oder schöpft Energie aus Lachen, um kosmische Energie für Pocopoc zu gewinnen.", completion = "Die Macht singt. Eine neue Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64889] = { id = 64889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Zereth Mortis zusammenfügt", description = "Die Chiffren sind der Schlüssel. Jede ein Schritt auf dem Weg. Ihr müsst sie alle finden.\n\nGeht in die innere Kammer. Die Anordnung des Primus Locus wartet.\n\nDer erste Schritt zum Aufstieg. Zu dem Gefäß.", sourceObjective = "Studiert die Anordnung des Locus und benutzt die Locusverschiebung, um den Ultimus Locus zu erreichen.", progress = "Sammelt die Chiffren, um zur Tür zu gelangen, wo das Gefäß wartet.", completion = "Der letzte Abschnitt der Reise beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64935] = { id = 64935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hart auf Hart", description = "<Schutthaufen sind in der Gegend verstreut. Die Verschlinger haben genug Schaden verursacht, um die gesuchte Chiffre zu verstecken.\n\nVielleicht könnte man einen der Diener in der Nähe dazu bringen, den Schutt wegzuräumen.>", sourceObjective = "Zerschmettert das Geröll, das den Weg zur Anordnung des Secundus Locus versperrt.", completion = "Unsere Reise geht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[64936] = { id = 64936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oben, unten, überall", description = "Drei Schlösser an der Tür, drei Schlüssel auf dem Zenith verborgen.\n\nFindet die Losungen. Sprecht die Worte. Sichert das Gefäß.", sourceObjective = "Sammelt die Losungen auf dem Ultimus Locus, die Ihr für das Gefäß braucht.", completion = "Wo eine Reise endet, beginnt eine neue.", sourceObjectiveStatus = "unverified-source-field" }
quests[64937] = { id = 64937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht meines Lebens", description = "Große Macht weckt großen Hunger. Die unersättlichen Verschlinger erklimmen die Klippen auf der Suche nach Nahrung.\n\nBald werden sie über das Plateau hereinbrechen. Sie wollen alles verschlingen, das sie finden. Das Gefäß. Seine Macht. Uns.\n\nDas darf nicht geschehen. Setzt dieses Automa ein. Lasst ihr geiferndes Geheul verstummen.", sourceObjective = "Verteidigt mit Pocopoc das Gefäß gegen die Verschlinger.", completion = "Sicherheit, für den Augenblick. Eine größere Aufgabe wartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64941] = { id = 64941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnerseele", description = "<Die Hühnerseele ist munter und hungrig. Ihr könnt jetzt die Gestalt des Huhns nutzen.>", sourceObjective = "Bringt die Hühnerseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Huhn! Jetzt könnt Ihr auch gackern wie eines!", sourceObjectiveStatus = "unverified-source-field" }
quests[64942] = { id = 64942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Primus", sourceObjective = "Sprecht mit Tal-Inara in Oribos, um zur Kammer der Richterin zu reisen.", completion = "Uns fehlt noch ein letztes Siegel, um Zovaal zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64944] = { id = 64944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine hastige Reise", description = "Der Weg nach Zereth Mortis steht offen.\n\nHier muss ich Euch verlassen. Den Ewigen ist es verboten, an den Ort ihrer Schöpfung zurückzukehren. Zovaal hat das heiligste Gesetz der Progenitoren gebrochen.\n\nDiese Reise müsst Ihr allein antreten.\n\nGeht. Findet eine sichere Stellung in Zereth Mortis, damit die Streitkräfte der Pakte Euch folgen können.\n\nDann werden wir den Kerkermeister jagen und diesem Wahnsinn ein Ende setzen.", sourceObjective = "Beginnt Eure Reise nach Zereth Mortis, indem Ihr auf den Animawyrm aufsitzt.", completion = "Das ist... eindeutig nicht Oribos.", sourceObjectiveStatus = "unverified-source-field" }
quests[64945] = { id = 64945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde in einem fremden Land", description = "Haben wir... Haben wir Zereth Mortis erreicht? Und wandeln wir gerade über Wasser?\n\nWas für ein wundervoller Ort! Zumindest, was ich durch diesen Nebel sehen kann.\n\nIch glaube, da hinten steht ein Bauwerk. Vielleicht finden wir dort ein paar Antworten.", sourceObjective = "Begleitet Pelagos und erforscht die Umgebung.", completion = "Ich werde nicht zulassen, dass Agenten des Kerkermeisters dieses Land entweihen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64947] = { id = 64947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr mal 'ne Hand frei?", description = "Um den Kerkermeister aus Zereth Mortis zu vertreiben, müssen wir all unsere Ressourcen gegen den Feind aufbringen.\n\nIn einem Repositorium ganz in der Nähe liegt ein Objekt von potenzieller Macht, aber die Verteidigung der Kammer reagiert nur auf Automas. Ich würde niemals einem von ihnen schaden, aber ich habe eins gefunden, das nicht mehr funktioniert.\n\nWenn Ihr seine Hand extrahiert, könnte uns diese inaktive Gliedmaße Zugang zu dem Repositorium verschaffen.\n\nIch verabscheue es eigentlich, die Schöpfung der Ersten so zu missbrauchen, aber wir dürfen nicht zulassen, dass die Schlundgebundenen dieses Reich besudeln.", sourceObjective = "Helft Firim.", completion = "Ich gebe zu, dieses Ergebnis hatte ich nicht erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64949] = { id = 64949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur zu Forschungszwecken", description = "Während meiner Zeit in Zereth Mortis habe ich mir stets die größte Mühe gegeben, die Automas nicht zu stören, und bisher haben sie mich kaum beachtet.\n\nEs scheint, als hätte sich das mit den jüngsten Ereignissen geändert.\n\nLasst es mich noch einmal ganz deutlich sagen: Ich will die Schöpfungen der Ersten auf keinen Fall verletzen. Aber sollte im Laufe Eurer Bemühungen ein Konflikt mit den Automas unausweichlich werden, müssen wir dafür sorgen, dass er nicht umsonst war.\n\nWenn ich die Fragmente gefallener Automas untersuche, finde ich vielleicht etwas, das uns gegen die Schlundgebundenen hilft.\n\nSeid vorsichtig.", sourceObjective = "Sammelt 12 intakte Automafragmente von alarmierten Automas im Vestibül der Genesis.", progress = "Habt Ihr irgendwelche hilfreichen Fragmente gefunden?", completion = "Der Verlust dieser Automas ist zwar bedauerlich, aber die Fragmente könnten meine Forschungen ein gutes Stück voranbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64950] = { id = 64950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenseitiger Austausch", description = "Es scheint, als wären die Automas nicht gerade glücklich, dass wir uns die Hand ihres Kollegen geholt haben. Sie sind ausgesprochen feindselig.\n\nLeider können wir nicht zulassen, dass dies unseren Fortschritt aufhält.\n\nDie Hand des Automa sollte eine Konsole im Repositorium der Genesis aktivieren. Ich glaube, darin befindet sich ein Objekt mit großem Potenzial.\n\nWenn Ihr es habt, zeige ich Euch einen Ort, über den Ihr vielleicht Eure Verbündeten erreicht, die Ihr zurückgelassen habt.\n\nSeid Ihr einverstanden?", sourceObjective = "Aktiviert mit der Automahand eine Automakonsole und holt Euch den Schatz des Repositoriums.", progress = "Habt Ihr das Objekt aus der Konsole?", completion = "<Firim reißt Euch den Kern förmlich aus den Händen.>\n\nFaszinierend. Ich habe schon viele Automakerne untersucht, aber dieser hier strahlt eine mir vollkommen neue Energie aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[64951] = { id = 64951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg in Zuflucht", description = "Ich hätte nicht gedacht, dass ich heute <einen lebendigen Sterblichen/eine lebendige Sterbliche> und einen Kyrianer treffe, aber Eure Hilfe war ein wahrer Segen.\n\nBevor ich mich näher mit diesem Automakern beschäftige, führe ich Euch noch zur Zuflucht. Unsere Expedition hat diese Siedlung gegründet.\n\nMeine Kollegen haben mich zwar verbannt, weil ich ihre dogmatischen Lehren der \"Erleuchteten\" infrage stellen wollte, aber ich würde es trotzdem nur ungern sehen, wenn der Kerkermeister die Zuflucht einfach auslöscht.\n\nHelft ihnen, dann helfen sie Euch vielleicht, zu Euren Verbündeten zurückzukehren. Das Gleichgewicht von Geben und Nehmen liegt schließlich in der Natur aller Mittler.", sourceObjective = "Verlasst mit Firim das Repositorium der Genesis.", completion = "Hier muss ich Euch verlassen.\n\nMeine ehemaligen Kollegen und ich haben... philosophische Differenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64952] = { id = 64952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung der Zerstörer", description = "Die Schlundgebundenen besitzen furchtbare Waffen, die dunkle Magie sammeln und gegen unsere Tore schleudern.\n\nDie Verteidigungsbarriere um die Zuflucht wird nicht mehr lange halten. Und dann wird alles, was wir sind, alles, was uns wichtig ist, einfach ausgelöscht.\n\nWenn Ihr wirklich seid, wer Ihr behauptet zu sein, dann beweist es uns. Zerstört die Waffen des Feindes und rettet unser Zuhause.\n\nIch bete zu den Ersten, dass Ihr Erfolg habt.", sourceObjective = "Vernichtet 4 Schlundzerstörer.", completion = "Ihr habt uns etwas Zeit verschafft, Sterblicher. Der Segen der Ersten sei mit uns allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64953] = { id = 64953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Zuflucht", description = "Die Schlundgebundenen versammeln sich direkt vor unseren Toren. Sie planen eindeutig, uns zu überrennen!\n\nDie Erleuchteten wollen doch nur die Wunder der Ersten in Frieden ehren. Die Verteidigungsbarriere der Zuflucht soll uns lediglich vor kleineren Gefahren schützen. Wir hätten niemals erwartet, dass die Streitkräfte des Kerkermeisters uns angreifen würden.\n\nIhr sagt, wir wären Verbündete, <Sterblicher/Sterbliche>? Dann helft uns, dieses heilige Land zu beschützen.", sourceObjective = "Besiegt 13 Schlundgebundene im Großen Veld.", progress = "So können unsere Pilger ihren Weg nicht fortsetzen.", completion = "Ihr habt Euren Mut mehr als bewiesen, aber das scheint den Feind nur anzustacheln.", sourceObjectiveStatus = "unverified-source-field" }
quests[64957] = { id = 64957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Portalstein", description = "Der Kerkermeister hat seine Streitmacht zurückgezogen. Ich sollte erleichtert sein, aber ich fürchte, das heißt nur, sie haben einen Weg in das Mausoleum gefunden.\n\n<Die Älteste Ara schaudert.>\n\nTrotz der Zweifel des Ältesten Kreth habt Ihr Euch als <wahrer Verbündeter/wahre Verbündete> erwiesen. Und davon könnten wir noch mehr brauchen.\n\nDirekt nach unserer Ankunft in Zereth Mortis haben wir einen inaktiven Portalstein gefunden. Wenn Ihr tatsächlich <ein Schlundgänger/eine Schlundgängerin> seid und die Prophezeiungen stimmen, dann könnt Ihr ihn aktivieren.\n\nUnd wenn Eure Verbündeten diesen heiligen Ort retten können, dann müssen wir ihnen einen Pfad ebnen.\n\nKommt.", sourceObjective = "Öffnet den Portalstein nach Oribos.", completion = "Schlundgänger! Dem Licht sei Dank, dass Euch und Pelagos nichts geschehen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[64958] = { id = 64958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Streitkräfte sammeln sich", sourceObjective = "Sprecht mit dem Ältesten Kreth in Zereth Mortis.", completion = "Ihr habt die Zuflucht beschützt und nun bringt Ihr Verbündete, um dieses heilige Land zu beschützen.\n\nDer Segen der Ersten sei mit Euch, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[64959] = { id = 64959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otterseele", description = "<Die Otterseele ist flink und prahlerisch. Ihr könnt jetzt die Gestalt des Otters nutzen.>", sourceObjective = "Bringt die Otterseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Otter! Jetzt könnt Ihr Euch auch wie einer im Wasser treiben lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64960] = { id = 64960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annelidenfütterung" }
quests[64961] = { id = 64961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenseele", description = "<Die Katzenseele ist elegant und neugierig. Ihr könnt jetzt die Gestalt der Katze nutzen.>", sourceObjective = "Bringt die Katzenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, eine Katze! Jetzt könnt Ihr auch Eure Beute wie eine anspringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64962] = { id = 64962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie prophezeit", description = "Die Sphären sind im Einklang. Die Melodie ertönt. Geht, lasst den Chor der Seher erschallen. Möge der Zyklus der Wiedergeburt beginnen.", sourceObjective = "Bringt Firim und die Seher in die Mitte.", progress = "Das Lied erwartet seinen Chor.", completion = "Das Rascheln der Schöpfung, das Flüstern im Dunkel. Lasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64963] = { id = 64963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anforderung eines Überläufers", description = "<Als Ihr die Schriftrolle ausrollt, erkennt Ihr, dass es sich um ein codiertes Waffenrequisitionsformular der Maldraxxi von Todesende an ihre Venthyrverbündeten handelt... allesamt Diener des Kerkermeisters.\n\nBeim Vorstoß des Todes in Korthia muss es doch jemanden geben, der Euch helfen kann, diesen Code zu knacken und so in Erfahrung zu bringen, wie ihre genauen Pläne lauten.>", sourceObjective = "Liefert das Sendschreiben bei Herzogin Mynx in der Zuflucht des Hüters in Korthia ab.\n\nBereitgestellter Gegenstand:", completion = "<Ein Lächeln breitet sich auf dem Gesicht von Herzogin Mynx aus, als sie die von Euch beschaffte Schriftrolle liest. Einen Augenblick später lacht sie schallend los.>\n\nDie Streitkräfte des Kerkermeisters nutzen solch eine erbärmliche Verschlüsselung! In Eurer Schriftrolle steht zwar nicht, wo genau, aber offenbar wartet eine Truhe mit Waffen auf uns. Ein Trupp Eurer Verbündeten sollte dem nachgehen und sie ohne Weiteres bergen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[64964] = { id = 64964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euren Kämpfer", description = "Die Streitmacht des Kerkermeisters hinterlässt unglaubliche Schäden in Provis Strata und der Umgebung. Wenn ihnen niemand Einhalt gebietet, verlieren wir all das Wissen in dieser Region.\n\nEiner von uns hat einige Automas vorbereitet, um die Schlundgebundenen zu vernichten. Vereint Eure Kräfte und bekämpft alle, die Zereth Mortis so schändlich missachten.", sourceObjective = "Wählt ein Automakonstrukt aus und kämpft damit gegen die Schlundgebundenen.", progress = "Habt Ihr den Auftrag erfüllt?", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64969] = { id = 64969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Unkraut", description = "Jetzt verstehe ich, warum der Älteste Nirav so besorgt ist.\n\nViele der Pilger, die zu den Katalysatorstationen aufgebrochen waren, sind noch nicht zurückgekehrt. Unter ihnen auch Feroz, der wahrscheinlich über die Informationen verfügt, die wir für die Wiederherstellung der Überreste benötigen.\n\nBereitet Euch vor. Am Katalysator wimmelt es nur so von den jüngsten Schöpfungen der Ersten. Wenn es dort ein Problem gibt, könnte es sehr gefährlich werden.", sourceObjective = "Trefft Euch mit der Ältesten Ara vor den Katalysatorstationen.", completion = "Feroz hat mir erklärt, was mit den vermissten Pilgern geschehen ist.\n\nSie sind in den Katalysatorstationen gefangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64970] = { id = 64970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anachronistischer Schlüsselstein: Die Verheerten Inseln", description = "Ich bin unlängst in den Besitz eines einzigartigen Schlüsselsteins gelangt. Er mag zwar alt und verschlissen aussehen, aber ich glaube, dass er immer noch eine Geschichte zu erzählen hat.\n\nNehmt ihn doch mit. Vielleicht dient er Euch ja als Erinnerung an längst vergangene Abenteuer. Abenteuer, von denen Ihr mir hoffentlich erzählen werdet.", sourceObjective = "Schließt einen anachronistischen Schlüsselsteindungeon ab.", completion = "Eure Abenteuergeschichten sind höchst spannend! Bitte erlaubt mir, Euch ein Zeichen meiner Dankbarkeit zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64974] = { id = 64974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal aufwischen bitte" }
quests[64977] = { id = 64977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring frei", description = "Ein bemerkenswerter Aspekt dieser Lande ist, dass sie sich schnell ändern und anpassen können, obwohl sie schon so lange bestehen. Nichts stagniert an diesem Ort.\n\nIn den Tiefen des Nexus der Verwirklichung liegt eine Schmiede, die anscheinend für die Erprobung und Erforschung dieser Entwürfe geschaffen wurde. Eines Tages müssen diese Wesen Zereth Mortis vielleicht vor einer drohenden Gefahr beschützen. Ihr solltet also jede Gelegenheit nutzen, ihre Effektivität zu testen.\n\nGeht dorthin, stellt Euch den Kreationen der Schmiede und erstattet mir dann Bericht.", sourceObjective = "Besiegt erzeugte Schöpfungen im Nexus der Verwirklichung.", completion = "Was für eine bemerkenswerte Apparatur. Ganz offensichtlich lassen sich ihre Schöpfungen noch verbessern, aber vielleicht lernt sie ja etwas aus der Lektion, die Ihr sie gelehrt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64984] = { id = 64984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häschenseele", description = "<Die Häschenseele ist schlau und flink. Ihr könnt jetzt die Gestalt des Häschens nutzen.>", sourceObjective = "Bringt die Häschenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Häschen! Jetzt könnt Ihr auch hoppeln wie eines!", sourceObjectiveStatus = "unverified-source-field" }
quests[64985] = { id = 64985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattenseele", description = "<Die Rattenseele ist neugierig und gesellig. Ihr könnt jetzt die Gestalt der Ratte nutzen.>", sourceObjective = "Bringt die Rattenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[64988] = { id = 64988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenseele", description = "<Die Schlangenseele ist geduldig und wachsam. Ihr könnt jetzt die Gestalt der Schlange nutzen.>", sourceObjective = "Bringt die Schlangenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, eine Schlange! Denen entgeht nie was, weil sie nie blinzeln müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64989] = { id = 64989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachelschweinseele", description = "<Die Stachelschweinseele ist vorsichtig und scheu. Ihr könnt jetzt die Gestalt des Stachelschweins nutzen.>", sourceObjective = "Bringt die Stachelschweinseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Stachelschwein! Manche halten sie ja für unnahbar, aber ich finde sie nett.", sourceObjectiveStatus = "unverified-source-field" }
quests[64990] = { id = 64990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillenseele", description = "<Die Grillenseele ist ein Glückspilz. Ihr könnt jetzt die Gestalt der Grille nutzen.>", sourceObjective = "Bringt die Grillenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, eine Grille! Jetzt könnt Ihr auch hüpfen wie eine!", sourceObjectiveStatus = "unverified-source-field" }
quests[64992] = { id = 64992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präriehundseele", description = "<Die Präriehundseele ist immer hellwach. Ihr könnt jetzt die Gestalt des Präriehunds nutzen.>", sourceObjective = "Bringt die Präriehundseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Präriehund! An Euch kommt nichts vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[64993] = { id = 64993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauroliskenjungtierseele", description = "<Die Sauroliskenjungtierseele ist zäh und wild. Ihr könnt jetzt die Gestalt des Sauroliskenjungtiers nutzen.>", sourceObjective = "Bringt die Sauroliskenjungtierseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Sauroliskenjungtier! So niedlich und doch so wild!", sourceObjectiveStatus = "unverified-source-field" }
quests[64994] = { id = 64994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Froschseele", description = "<Die Froschseele ist eine Frohnatur und sehr musikalisch. Ihr könnt jetzt die Gestalt des Froschs nutzen.>", sourceObjective = "Bringt die Froschseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Frosch! Sie sind wahre Gesangskünstler!", sourceObjectiveStatus = "unverified-source-field" }
quests[64995] = { id = 64995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauridenseele", description = "<Die Sauridenseele ist schelmisch und verspielt. Ihr könnt jetzt die Gestalt des Sauriden nutzen.>", sourceObjective = "Bringt die Sauridenseele zu Choofa im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ooh, ein Saurid! Da hat Lady Mondbeere mal mit einem größeren Exemplar einen Krieg der Streiche geführt. Hek hek hek!", sourceObjectiveStatus = "unverified-source-field" }
