quests[65008] = { id = 65008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegenseele", description = "<Die Ziegenseele ist stoisch und unerschütterlich. Ihr könnt jetzt die Gestalt der Ziege nutzen.>", sourceObjective = "Bringt die Ziegenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Ziege. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65009] = { id = 65009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widderseele", description = "<Die Widderseele ist mutig und wild. Ihr könnt jetzt die Gestalt des Widders nutzen.>", sourceObjective = "Bringt die Widderseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Widder. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65010] = { id = 65010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpakaseele", description = "<Die Alpakaseele ist argwöhnisch und wachsam. Ihr könnt jetzt die Gestalt des Alpakas nutzen.>", sourceObjective = "Bringt die Alpakaseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, das Alpaka. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65020] = { id = 65020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Anwendungen", description = "Seid gegrüßt, <Schlundgänger/Schlundgängerin>.\n\nIch freue mich bekanntzugeben, dass wir die nötige Forschung zur Platzierung eines Feldanimaumleiters gesammelt haben.\n\nBitte sucht eine passende Position dafür im Reliquiar - idealerweise an einem Ort ohne Interferenz durch andere animageladene Relikte.", sourceObjective = "Platziert den Feldanimaumleiter im Reliquiar der Erinnerung.", completion = "Das ist ein guter Platz für den Feldanimaumleiter.\n\nEiner der größten Nutzen, die wir aus unserer Forschung ziehen werden, ist womöglich eine Verringerung des nötigen Aufwands.", sourceObjectiveStatus = "unverified-source-field" }
quests[65021] = { id = 65021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adlerseele", description = "<Die Adlerseele ist mutig und wachsam. Ihr könnt jetzt die Gestalt des Adlers nutzen.>", sourceObjective = "Bringt die Adlerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Adler. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65022] = { id = 65022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporenseglerseele", description = "<Die Sporenseglerseele ist flink und wachsam. Ihr könnt jetzt die Gestalt des Sporenseglers nutzen.>", sourceObjective = "Bringt die Sporenseglerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Sporensegler. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
