quests[65024] = { id = 65024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenschlangenseele", description = "<Die Wolkenschlangenseele ist dynamisch und loyal. Ihr könnt jetzt die Gestalt der Wolkenschlange nutzen.>", sourceObjective = "Bringt die Wolkenschlangenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Wolkenschlange. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65025] = { id = 65025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberseele", description = "<Die Eberseele ist wild und gerissen. Ihr könnt jetzt die Gestalt des Ebers nutzen.>", sourceObjective = "Bringt die Eberseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Eber. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65026] = { id = 65026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eulenseele", description = "<Die Eulenseele ist ernst und klug. Ihr könnt jetzt die Gestalt der Eule nutzen.>", sourceObjective = "Bringt die Eulenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Eule. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65031] = { id = 65031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtfelder", description = "Champions der Horde und der Allianz kämpfen auch weiterhin auf unzähligen Schlachtfeldern. Die Mittler des Kartells Zo bezahlen Kämpfer, um deren Taktiken beobachten zu können.\n\nWerdet Ihr dem Ruf folgen und Euch ins Gefecht stürzen?", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Die Mittler des Kartells Zo werden über Eure Wahl erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65032] = { id = 65032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtfeldbeobachter", description = "Ihr findet Zo'Sorg und die anderen Mittler des Kartells Zo direkt dort hinten.\n\nSie werden sicherlich erfreut sein zu hören, dass groß angelegte Schlachten auch Teil der Vorsehung sind.", sourceObjective = "Sprecht mit Stratege Zo'rak in Oribos.", completion = "Das Kartell Zo ist ein verlässlicher Partner. Ihr habt eine gute Wahl getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65033] = { id = 65033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegesobservation", sourceObjective = "Gewinnt ein beliebiges Schlachtfeld.", completion = "Der Sieg ist nie gewiss. Kehrt morgen zu einer weiteren Observation zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[65034] = { id = 65034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", description = "Kehrt morgen zu einer weiteren Observation zurück.\n\nBis dahin wird Euch Tal-Inara dabei helfen, Eure Anstrengungen in eine produktive Richtung zu lenken.", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Das Kartell Zo lobt Eure Mühen. Die Vorsehung ist klar.", sourceObjectiveStatus = "unverified-source-field" }
quests[65035] = { id = 65035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", description = "Die Zusammenarbeit mit Euch war fantastisch, <Schlundgänger/Schlundgängerin>. Ihr solltet diese Informationen zu der Person zurückbringen, die Euch hierher entsandt hat.\n\nIch? Oh, ich bleibe mit meiner nützlichen Kiste hier.\n\nIhr könnt gerne jederzeit wiederkommen. Womöglich habe ich dann sogar ein paar neue Aufgaben für Euch!", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Ihr seid einem wahnsinnigen Mittler mit einer... Kiste begegnet?\n\nDann ist meine Erleichterung umso größer, Euch unversehrt wiederzusehen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[65036] = { id = 65036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainieren wie wir kämpfen", description = "Durch Ringe zu fliegen, hilft, die Grundlagen zu erlernen, aber wir trainieren so unerbittlich, wie wir kämpfen.\n\nVersucht nun, ein wenig in der Umgebung zu 'Segeln', bis Ihr den Bogen heraushabt. Natürlich müsst Ihr auf die Wildtiere achten und Eure Augen nach möglichen Gefahren offenhalten, aber deswegen trainieren wir ja.\n\nMeldet Euch bei Glutthal zurück, sobald Ihr bereit seid. Viel Glück!", sourceObjective = "Übt 'Segeln'.", progress = "Der Wind frischt auf.", completion = "Die Zeit wird knapp. Ein Sturm zieht auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[65045] = { id = 65045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmrisskrater", description = "Derwischians Bericht ist beunruhigend. Eine feindliche Streitmacht, die sich selbst als Primalisten bezeichnet, ist in den Sturmrisskrater eingefallen und hat die Schwarzschuppen am Belagerungshort festgenagelt.\n\nDie Eindringlinge beschwören gewaltsame Elementare und rekrutieren die grausamen Tarasek für ihre Sache.\n\nAzurathel wird am Krater Eure Hilfe brauchen. Durch Flügel oder Kralle, rettet unsere Leute.\n\nSobald die Schwarzschuppen in Sicherheit sind, veranlasst ein Treffen zwischen ihrem Kommandanten und mir. Seid gewarnt. Sarkareth kann... reizbar sein.", sourceObjective = "Trefft Azurathel im Sturmrisskrater.", completion = "Nun, {class}, Ich hoffe, Ihr seid bereit Euch die Krallen schmutzig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65046] = { id = 65046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Primalisten", description = "Meine Erinnerungen sind noch immer benebelt von der Stasis, aber ich bin mir sicher, dass wir diesen Primalisten zuvor schon begegnet sind.\n\n<Derwischian beißt die Fangzähne zusammen.>\n\nEs hat keinen Zweck! Es fühlt sich an, als würde ich Fragmenten eines Traumes hinterherjagen, wenn ich versuche, mich zu erinnern.\n\nVielleicht schlagt Ihr Euch besser. Sucht nach Hinweisen, was... oder wer... diese Eindringlinge antreibt.", sourceObjective = "Findet Hinweise über die Ursprünge und Absichten der Primalisten.", completion = "Die Primalisten sprechen davon, einen furchtbaren Sturm zu entfesseln.\n\nIst es möglich, dass sich irgendwo auf den Inseln eine noch größere Bedrohung unter Verschluss befindet?", sourceObjectiveStatus = "unverified-source-field" }
quests[65049] = { id = 65049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischt die Tarasek auf", description = "Die Tarasek sind unberechenbar und wild. Wie urzeitliche Drakoniden sozusagen.\n\nNeltharion hat sie nie als viel mehr als Futter betrachtet. Übungsziele. Aber sie sind gerissene Jäger und tödlich, wenn sie in Rudeln vorgehen.\n\nSollten sie von den Primalisten elementare Macht erhalten, würden sie wesentlich gefährlicher werden.\n\nDas können wir nicht zulassen, {name}. Dünnt ihre Reihen aus.", sourceObjective = "Tötet 7 Tarasek.", completion = "Beklagt nicht den Verlust einiger Tarasek.\n\nWo einer ist, lauern noch viel mehr in den Schatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65050] = { id = 65050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine herbeigezauberte Armee", description = "Die Primalisten beschwören eine Elementararmee. Wir müssen annehmen, dass sie vorhaben, sie gegen unsere Truppen einzusetzen.\n\nNun, nicht solange wir Wache halten.\n\nLasst Feuer auf sie niedergehen, <Rufer/Ruferin>! Brennt diese Elementare von der Insel und schaltet ihre Beschwörer aus, bevor sie weitere herbeirufen.", sourceObjective = "Tötet 12 beschworene Elementare.", completion = "Beschworene Elementare mögen nicht der befriedigendste Gegner sein, aber es ist ein gutes Gefühl, unsere Flügel wieder auszubreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65052] = { id = 65052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzschuppen", description = "Wir haben es hinter den Primalisteneinfall geschafft. Nun müssen wir den Hort erreichen.\n\nSchuppenkommandant Sarkareth ist hart im Nehmen und sein Weyrn hält stand. Aber ein Drache hat die Schwarzschuppen festgenagelt.\n\nEs ist an der Zeit, dem Kampf beizutreten!\n\nGeht voran. Gebt das Signal, wenn wir in Reichweite des Drachen sind. Dann schlagen wir mit sämtlichen uns zur Verfügung stehenden Kräften zu.\n\nNehmt Euch vor Hinterhalten in Acht. Ich habe kein gutes Gefühl dabei.", sourceObjective = "Gelangt zu Schuppenkommandant Sarkareth.", completion = "Ihr kämpft gut, {class}, aber wir hatten das unter Kontrolle.\n\nDie Schwarzschuppen kümmern sich um ihre Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[65053] = { id = 65053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenlungenkappe" }
quests[65054] = { id = 65054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainingsattrappen" }
quests[65055] = { id = 65055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschützende Kohlenpfannen" }
quests[65056] = { id = 65056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst ihn nicht entglitschen" }
quests[65057] = { id = 65057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu Glutthal", description = "Nun, da der Kampf vorüber ist, erwartet Ihr, dass ich Glutthal Bericht erstatte. Erwartet Azurathel, dass ich ihren Befehlen folge?\n\nIch denke nicht.\n\nDie Schwarzschuppen sind einzig dem Erdwächter unterstellt. Und bis jetzt habe ich keine Befehle von Neltharion erhalten.\n\n<Sarkareths Blick verfinstert sich.>\n\nDennoch bin ich nicht blind gegenüber der Bedrohung, welche diese Primalisten darstellen. Ich bin mir sicher, dass ich ihre Art zuvor schon bekämpft habe und dennoch...\n\nWir werden am Boden vorstoßen, wenn meine Leute wieder einsatzbereit sind. Wegtreten, <Rufer/Ruferin>.", sourceObjective = "Erstattet Glutthal Bericht.", completion = "Die Primalisten ermächtigten ihren Anführer durch eine Art Ritual?\n\nErzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[65060] = { id = 65060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaldera der Heiler", description = "Eure Vision vom arkanen Leuchtfeuer hat offenbart, dass Dracthyr in ihren Horten eingesperrt sind. Wir können es uns nicht erlauben, noch mehr unserer Leute zu verlieren.\n\n<Glutthal hält mit gerunzelter Stirn inne.>\n\nDie Heilschwingen sind die besten Heiler in unseren Rängen. Ihr Hort liegt innerhalb der Kaldera der Heiler. Glutdresch kennt den Weg.\n\nLasst niemanden zurück, <Rufer/Ruferin>.", sourceObjective = "Trefft Glutdresch in der Kaldera der Heiler.", completion = "Seht nur all die Verwundeten...\n\nDrinnen sind noch mehr Heiler. Wir müssen ihnen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65063] = { id = 65063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Bau", description = "Was auch immer das für ein Gift ist, dass sich in diesem Hort ausgebreitet hat, es ist stark genug, selbst unsere besten Heiler auszuschalten.\n\nDas verheißt nichts Gutes, weder für mich noch für Euch, {name}.\n\nAber das spielt keine Rolle. Dort sitzen Dracthyr in der Falle. Wir gehen rein, egal wie riskant.\n\nAtmet tief durch und folgt mir!", sourceObjective = "Folgt Glutdresch, um Viridia zu finden.", completion = "Gut, Ihr seid wach.\n\n<Viridia räuspert sich.>\n\nWir benötigen jetzt die Fertigkeiten eines Rufers.", sourceObjectiveStatus = "unverified-source-field" }
quests[65064] = { id = 65064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht mal wer da ist!", description = "Was für eine großartige Kreatur!\n\nSiloh sagt, dass wir keine Ressourcen für ein weiteres meiner \"abnormalen Haustiere\" hätten.\n\nAber wir könnten E'rnee vielleicht so verändern, dass ich ihn behalten kann. Zwischen den Kreaturen und dieser Umgebung treten seltsame Interaktionen auf. Wir können ihn vielleicht kleiner machen.\n\nIch kenne einen Ort, an dem wir unsere Forschung durchführen können. In der Nähe gibt es Blumen, chromatische Rosiden, die eine Reaktion auslösen könnten. Wollt Ihr nicht vielleicht unterwegs ein paar von ihnen einsammeln?", sourceObjective = "Sammelt 6 chromatische Rosiden in der Nähe der Dimensionenfälle.", progress = "Wir müssen einen Weg finden, damit E'rnee bei uns bleiben kann.", completion = "Vielleicht sollten wir noch mit ein paar anderen Testsubjekten experimentieren, bevor wir das an E'rnee ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65065] = { id = 65065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tuskarr", description = "Oh, entschuldigt, aber wir wussten nicht, dass Euer Volk auf dieser Insel lebt. Wir sind erst vor Kurzem in diesen Gefilden angekommen und suchen nach einem freien Land, das wir zu unserer Heimat machen können. Wir sind keine Bedrohung und werden weiterziehen, sollte dieses Land uns wirklich verboten sein.\n\nMeinem Sohn To'no haben es vor allem die verschiedenen Drachkin angetan und er hätte sicher viele Fragen an Euch. Er ist mein kleiner Entdecker. Wenn Ihr ihn vor mir seht, dann macht Euch auf eine Menge Fragen gefasst.\n\nWo ist der Bursche jetzt schon wieder hin?", sourceObjective = "Findet To'no.", completion = "Oh! Drachkin! Ihr seid dünner als die anderen. Oh! Und Ihr habt Flügel! \n\nÄh... Halpa?", sourceObjectiveStatus = "unverified-source-field" }
quests[65066] = { id = 65066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Floraaroma", description = "Vielleicht sollten wir nicht mit E'rnee herumexperimentieren, ohne vorher die Effekte zu kennen.\n\nBehaltet den Rest dieser Rosiden. Wir könnten mehr Experimente durchführen. Einige der Kreaturen beim Wasserfall sind zahm und kämen dafür infrage.\n\nLasst uns herausfinden, ob unterschiedliche Kreaturen verschieden auf das Rosidenaroma reagieren.", sourceObjective = "Experimentiert mit chromatischen Rosiden in der Nähe der Dimensionenfälle.", progress = "Diese Rosiden haben ein solch seltsames Aroma... Vielleicht reagieren die Kreaturen auf ganz eigene Weise darauf.", completion = "Die Resultate scheinen mir... nicht eindeutig zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65067] = { id = 65067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerbehälter", description = "Ich habe schon ein paar eigene Experimente durchgeführt, bevor Ihr gekommen seid.\n\nDiese Tests... sind aber nicht allzu gut verlaufen. Es hat sich gezeigt, dass einige Umgebungskomponenten die Kreaturen aggressiv machen können. Selbst einige der sanftesten Tiere wurden so zu Raubtieren.\n\nIch hab den Behälter mit den Komponenten fallen gelassen und bin geflüchtet. Aber ich weiß nicht mehr, wo das war.\n\nDer Behälter muss sich irgendwo inmitten der Herde der fleischfressenden Cerviden befinden. Wenn diese Blumen nicht funktionieren, brauchen wir den Behälter für unsere nächsten Testrunden.", sourceObjective = "Holt den Komponentenbehälter von den fleischfressenden Cerviden in der Nähe der Dimensionenfälle zurück.", progress = "Passt mit diesen fleischfressenden Cerviden auf, die beißen!", completion = "Ah. Das ist auf jeden Fall hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[65068] = { id = 65068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reichhaltige Kaskaden", description = "Viele der Kreaturen im Bereich der Dimensionenfälle sind von ganz besonderen Auswirkungen betroffen. Hm... Lasst uns mit den Wasserfällen selbst experimentieren!\n\nWir haben einzigartige Effekte durch die unterschiedlichsten Komponenten hier in Zereth Mortis feststellen können. Das könnte doch auch für das Wasser gelten?\n\nSammelt etwas Wasser von den Fällen ein und sprenkelt es über die Kreaturen, um zu sehen, was passiert.", sourceObjective = "Experimentiert mit Wasserfallwasser bei den Dimensionenfällen.", progress = "Diese Fälle müssen eine Art Magie enthalten, die wir nicht begreifen können.", completion = "Das war unerwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[65069] = { id = 65069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausmerzen des Mahlstroms", description = "Diese kleinen Duplikate von E'rnee waren nicht gerade freundlich.\n\nIrgendein Effekt der Fälle hat sie erschaffen. Sie sind nicht stabil. Habt Ihr gesehen, wohin sie verschwunden sind?\n\nWir müssen sie ausmerzen, bevor sie den anderen Tieren hier etwas antun. Kümmert Euch darum, während ich eine neue Probe aus den Fällen besorge.", sourceObjective = "Bezwingt 50 Duplikate von E'rnee.", completion = "Meine Güte... Was ist denn mit Euch passiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[65070] = { id = 65070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich ihn behalten?", description = "Oh nein. Was habe ich nur für ein Chaos an diesem heiligen Ort angerichtet.\n\nSeht. E'rnee fühlt sich zu Euch hingezogen. Es fällt mir gewiss nicht leicht... aber Ihr könnt Euch besser um ihn kümmern als ich.\n\nWenn wir diese Sache abgeschlossen haben, sollte er bei Euch bleiben.\n\nJetzt wissen wir wenigstens, dass die Fälle die Größe von Kreaturen verändern können. Versuchen wir es noch einmal.", sourceObjective = "Besprenkelt E'rnee mit Wasser.", progress = "Wenn das nicht funktioniert, können wir es ja einfach noch einmal versuchen!", completion = "Es hat funktioniert! Danke noch einmal für all Eure Hilfe. Er gehört jetzt Euch. Passt gut auf ihn auf.\n\nWiedersehen, E'rnee.", sourceObjectiveStatus = "unverified-source-field" }
quests[65071] = { id = 65071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halpa!", description = "Ich brauch Halpa!\n\nIch bin To'no und war auf Erkundung, da bin ich gut drin, aber ich habe nicht bemerkt, dass meine Schwester Ko mir gefolgt ist. Ich brauch Eure Halpa, sie zu finden, weil sie in Schwierigkeiten ist, also hab ich Eure Halpa, bitte?\n\nSie ist in diese Höhle gegangen, aber sie ist im Verstecken nicht so gut wie ich und unsere Eltern sind zu weit weg.\n\nKönnt Ihr sie finden, bevor es die Monster tun?", sourceObjective = "Rettet Klein Ko.", completion = "Ihr habt meine Kleinen gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[65072] = { id = 65072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlicher Arbeitsplatz", description = "Ranas Entdeckung der Progenitorrelikte bei den Zeitlosen Splittern hat unter den Erleuchteten für einige Aufregung gesorgt. Diese Relikte sind noch älter als unsere frühesten Entdeckungen und durch sie bekommen wir vielleicht einen tieferen Einblick in die komplexen Zusammenhänge von Zereth Mortis.\n\nRana sammelt jetzt gerade die Relikte, aber ich fürchte, sie ist in Gefahr. Agenten des Kartells Xy wurden in der Gegend gesichtet und werden gewiss versuchen, die Relikte zu stehlen.\n\nBitte reist zu den Zeitlosen Splittern und helft Rana, die Relikte einzusammeln.", sourceObjective = "Helft Rana bei ihrer Suche und sammelt 8 Progenitorrelikte.", progress = "Habt Ihr die Progenitorrelikte eingesammelt?", completion = "Eure Hilfe ist immer willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65073] = { id = 65073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein giftiges Problem", description = "Ihr erholt Euch schnell, {name}. Gut.\n\nDiejenigen, die meinem Hort entflohen sind, heilen, aber es sind noch mehr im Inneren gefangen. Wenn Ihr hineinstürmt, um sie zu retten, werde ich Euch nur wieder herausziehen müssen.\n\nRund um die Kaldera liegen Käfernester verteilt. Ihre Giftdrüsen könnten ein Mittel sein, um die Wirkung dieses Gifts zu neutralisieren.\n\nIch bin nicht dazu in der Lage, sie selbst einzusammeln. Ich muss auf Eure Fertigkeiten vertrauen, <Rufer/Ruferin>.", sourceObjective = "Sammelt 6 Giftdrüsen.", progress = "Die Zeit wird knapp.", completion = "Gut. Genau die brauche ich.\n\nIch werde an etwas arbeiten, das dem Gift entgegenwirkt. Damit könnt Ihr Euch wieder in den Hort wagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65074] = { id = 65074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Beute", description = "Die Wildnis rund um den Hort beheimatet Scythiden. Sie sind gefräßige Insektoide, oft territorial und aggressiv.\n\nAll die Verwundeten würden für diese Bestien leichte Beute abgeben. Ich will nicht, dass sie unsere Heiler angreifen, während sie sich erholen.\n\nTötet so viele von ihnen wie möglich, während ich mich nach Viridia umsehe.\n\nSie ist... sehr tapfer.", sourceObjective = "Tötet 4 Scythiden.", completion = "Die Scythiden waren schon immer außerordentlich stark, aber anscheinend sind sie während unserer Stasis noch größer und bedrohlicher geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65075] = { id = 65075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilschwingen", description = "<Rufer/Ruferin>, Ihr habt meinen Dank dafür, dass Ihr meinem Weyrn in seiner Stunde größter Not geholfen habt.\n\nNachdem wir unsere Stärke wiedererlangt haben, werden sich die Heilschwingen mit dem Rest unserer Truppen treffen.\n\nGlutdresch sagt mir, dass Glutthal ihren gesamten Weyrn verloren hat. Ich fürchte, ich verfüge nicht über die Magie, eine solche Wunde zu heilen.\n\nSie mag stoisch wirken, aber Glutthal schmerzt der Verlust zutiefst, {name}. Sagt ihr, dass ich unterwegs bin.", sourceObjective = "Sprecht mit Glutthal.", completion = "Ich bin erleichtert, dass Viridia lebt.\n\nFalls es stimmt, was Derwischian sagt, brauchen wir ihre Fähigkeiten in der kommenden Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65080] = { id = 65080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgeleitete Anima", description = "Jetzt schlägt die Stunde der Wahrheit.\n\nLagert sämtliche Anima, die Ihr bei Euch tragt, im Feldanimaumleiter hinter mir ein.\n\nMit etwas Glück bleiben Euch mögliche Nebenwirkungen erspart. Zum Beispiel Animaschwund, Ohnmacht oder Gedächtnisverlust... So was in der Art.", sourceObjective = "Lagert Anima im Feldanimaumleiter im Reliquiar der Erinnerung ein.", completion = "Ein durchschlagender Erfolg!\n\nIch gehe davon aus, dass sich der Umleiter jetzt und zukünftig als nützlich erweisen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[65081] = { id = 65081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Apfel am Tag" }
quests[65084] = { id = 65084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Froststeingewölbe", description = "Seht dort, auf der Insel! Primalistentruppen ziehen sich am Froststeingewölbe zusammen.\n\nDer Sturm, den sie entfesseln möchten, muss dort drinnen eingeschlossen sein.\n\n<Glutthal zuckt zusammen und ringt mit ihren zerrütteten Erinnerungen.>\n\nWir haben diesen Gegner schon einmal bekämpft... und wir haben gewonnen. Neltharion ordnete an, dass das Gewölbe geschützt werden soll, aber ich... weiß nicht mehr, warum...\n\nEs bleibt keine Zeit, um sich in Erinnerungen zu verlieren. Versammelt Euch mit Sarkareth und den Schwarzschuppen am Gewölbe. Sorgt dafür, dass der Feind nicht durchbricht!", sourceObjective = "Versammelt Euch beim Froststeingewölbe.", completion = "Ruhig Blut, {class}. Die Schwarzschuppen werden diesem Angriff ein Ende bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65087] = { id = 65087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beute im Inneren", description = "Die Primalisten wollen also, was im Gewölbe ist?\n\n<Sarkareth kneift die Augen zusammen.>\n\nLasst sie nur kommen.\n\nWir werden ihnen zeigen, wozu die Dracthyr geboren wurden!", sourceObjective = "Verteidigt das Gewölbe.", progress = "Wir verteidigen hier keinen Kinderhort, sondern etwas weitaus Gefährlicheres. Das spüre ich.\n\nDie Magie hinter dieser Barriere versucht alles, um auszubrechen. Haltet die Stellung und lasst diese Primalisten nicht vorbei.", completion = "Wir werden überrannt! Sie brechen in das Gewölbe ein!\n\nWo stecken diese schwarzen Drachen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[65089] = { id = 65089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfroscht" }
quests[65090] = { id = 65090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr weiterer verlorener Seelen", description = "Es strömen immer noch Seelen in den Schlund. Könntet Ihr Euch noch einmal hinauswagen, um mehr von ihnen zu retten?\n\nWir müssen seine Pläne durchkreuzen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 20 Seelen im Schlund.", completion = "Oh, Ihr habt noch so viele würdige Seelen gefunden!\n\nIch werde dafür sorgen, dass diese Seelen hier im Ardenwald gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65096] = { id = 65096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Ende oder meins", description = "Wir haben eine Fülle von Informationen aus den Relikten der Zeitlosen Splitter gewonnen.\n\nDie Schlundgebundenen wissen von dieser Entdeckung und wollen uns aufhalten. Sie haben im gesamten Gebiet Fallen gelegt, damit wir nicht mehr zu den Relikten kommen.\n\nWir dürfen nicht zulassen, dass der Kerkermeister uns den Weg zu diesen heiligen Relikten abschneidet.\n\nBitte beseitigt diese Bedrohung der Schlundgebundenen und stellt so viele Relikte sicher wie möglich.", sourceObjective = "Tötet Bestrafer Makaris und sammelt 6 heilige Relikte.", progress = "Habt Ihr die Relikte bei den Zeitlosen Splittern gesichert?", completion = "Seid gesegnet für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65097] = { id = 65097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauft!", description = "Stürme werden uns überrollen! Wir müssen evakuieren!\n\nRettet so viele, wie Ihr könnt. Und findet mir diese schwarzen Drachen!", sourceObjective = "Rückzug!", progress = "Dieser... Schmerz.", completion = "Ich danke Euch, {name}.\n\nEure Hilfe ist... unerwartet, aber begrüßenswert.", sourceObjectiveStatus = "unverified-source-field" }
quests[65098] = { id = 65098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konsequenzen des Mutes", description = "Danke, dass Ihr mich geheilt habt, {name}. Ich hoffe, dass wir unser gegenseitiges Vertrauen aufbauen können.\n\n<Furorion schaudert.>\n\nDie Sturmfresserin. Ich bin noch nie einem Drachen mit solch einer rohen Elementarenergie gegenübergestanden. Ob es noch mehr wie sie gibt?\n\nWartet... Wo ist Ebyssian? Hat er überlebt? Ihr müsst ihn finden!", sourceObjective = "Findet Ebyssian.", completion = "Gut, dass Ihr es nach draußen geschafft hab, {name}.\n\nAber... ich kann mir nicht helfen, ich fühle mich verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65100] = { id = 65100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Befehle", sourceObjective = "Organisiert die Evakuierung der Verbotenen Insel.", progress = "Wir gehen! Ich hätte nie gedacht, dass es so ausgeht, aber wir kommen besser vorbereitet zurück.", completion = "Ebyssian erzählte mir von einer Gruppe, die sich die Horde nennt. Er behauptet, sie legen Wert auf Ehre und Stärke. Wenn das stimmt, könnten sie sich uns gegenüber als würdig erweisen.\n\nEr sagt, ihr Rat würde von einer Stadt namens Orgrimmar aus regieren. Sieht aus, als hätten wir einen langen Flug vor uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[65101] = { id = 65101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ikonischer wie drakonischer Anblick", sourceObjective = "Nehmt Euer sterbliches Antlitz an.", progress = "Sterbliche können in der Gegenwart höherer Wesen so nervös sein.", completion = "Euer Antlitz steht Euch gut, {name}. Es ist ganz anders als die, die ich bisher sah!\n\nMöglicherweise finden wir heraus, warum sich das Antlitz eines {race} von dem eines Drachen unterscheidet, wenn wir mehr über Eure Herkunft erfahren.\n\nAber zunächst müssen wir uns auf eine Expedition vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65102] = { id = 65102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischaugen" }
quests[65103] = { id = 65103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr weiterer verlorener Seelen", description = "Seelen strömen nach wie vor in den Schlund. Wir müssen den Kurs halten und noch mehr würdige Seelen finden.\n\nKehrt zum Schlund zurück und rettet alle, die Ihr retten könnt.", sourceObjective = "Rettet 20 Seelen aus dem Schlund.", completion = "Gute Arbeit. Ich weiß, dass wir noch mehr vor diesem wahrhaft grausamen Dasein retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65104] = { id = 65104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr weiterer verlorener Seelen", description = "<Schlundgänger/Schlundgängerin>, wir müssen noch mehr tun, um den Kerkermeister von seiner Machtquelle abzuschneiden... und dafür sorgen, dass er keine weiteren Seelen bekommt.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 20 Seelen im Schlund.", completion = "Ausgezeichnet, Schlundgänger. Unsere Armeen hier werden mit jeder Seele, die Ihr zurückbringt, stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[65105] = { id = 65105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr weiterer verlorener Seelen", description = "Immer mehr Seelen strömen in den Schlund.\n\nIch sehe keinen Grund, warum Ihr nicht noch mehr Seelen aus dem Abgrund retten könntet.\n\nKehrt zum Schlund zurück und findet dort weitere erlösenswerte Seelen für mich.", sourceObjective = "Rettet 20 Seelen im Schlund.", completion = "Eine weitere ausgezeichnete Sammlung von Seelen, nicht zu gebrochen, nicht zu ausgelaugt und nicht zu unschuldig.\n\nIch weiß schon genau, wohin ich diese Seelen auf ihrem Weg zur Erlösung schicke.", sourceObjectiveStatus = "unverified-source-field" }
quests[65115] = { id = 65115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lösung auf der Spur" }
quests[65117] = { id = 65117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Proben" }
quests[65118] = { id = 65118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenflug leicht gemacht", description = "Fangen wir mit den Grundlagen an.\n\nWenn Ihr geradeaus fliegt, werdet Ihr sehr schnell erschöpft sein. Nutzt die Schwerkraft und zielt leicht nach unten, um eine lange Strecke zu fliegen. Die Ringe zeigen Euch den allgemeinen Winkel an, den Ihr für den einfachen Gleitflug verwenden solltet.\n\nZuerst, ruft Euren Drachen herbei. Alternativ kann unser roter Drachenfreund hier Euch mitnehmen.\n\nDann fliegt durch die Ringe und landet am Zielort.\n\nWenn Ihr irgendwo festhängt, benutzt die bronzene Taschenuhr und Celormu wird Eure Position zurücksetzen.", sourceObjective = "Beschwört Euer Himmelsreittier oder steigt auf den roten Drachen. Gleitet anschließend durch die Ringe und landet im Zielgebiet.", progress = "Gut gemacht, 0xcp.", completion = "Exzellente Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[65119] = { id = 65119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Automas im Einsatz" }
quests[65120] = { id = 65120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensturzflug leicht gemacht", description = "Gleitend erreicht Ihr das gewünschte Ziel. Aber was, wenn Ihr schneller ankommen wollt?\n\nDurch den Sturzflug von einem hohen Punkt erhaltet Ihr einen Geschwindigkeitsschub.\n\nFliegt durch die Ringe zum Zielort.\n\nWenn Ihr irgendwo festhängt, benutzt die bronzene Taschenuhr und Celormu wird Eure Position zurücksetzen.", sourceObjective = "Führt einen Sturzflug aus, gleitet dann durch die Ringe und landet im Zielgebiet.", completion = "Seht Ihr? Das war viel besser.\n\nWenn Ihr den Flug mit einem Sturzflug beginnt, kommt Ihr viel schneller an das gewünschte Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65121] = { id = 65121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Baronin Vashj", sourceObjective = "<Baronin Vashj beäugt Euch mit großem Interesse.>\n\nNur weil wir einen gemeinsamen Freund haben, heißt das noch lange nicht, dass Ihr und ich auch Freunde sein werden...\n\nAber immerhin seid Ihr kampferprobt, so viel steht fest. Wir werden sehen, ob Ihr mich noch weiter beeindrucken könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65123] = { id = 65123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Lady Mondbeere" }
quests[65124] = { id = 65124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Mikanikos", sourceObjective = "<Mikanikos studiert Euch sorgfältig.>\n\nOh ja, {name}. Unser gemeinsamer Freund hält hohe Stücke auf Euch. Sehr interessant. Sehr faszinierend.\n\nBin schon sehr gespannt, mehr über Euch zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65126] = { id = 65126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Die Gräfin" }
quests[65128] = { id = 65128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Alexandros Mograine" }
quests[65129] = { id = 65129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Jagdhauptmann Korayn", sourceObjective = "<Jagdhauptmann Korayn nickt anerkennend.>\n\nUnser gemeinsamer Freund hat gesagt, Ihr hättet seit unserem letzten Treffen ziemlich viel zu tun gehabt. Ich habe auch ein paar beeindruckende Geschichten über Eure Jagden gehört. Ich begrüße die Gelegenheit, an Eurer Seite auf die Jagd zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65130] = { id = 65130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Polemarch Adrestes", sourceObjective = "<Polemarch Adrestes überfliegt einige der Notizen, die er mitgebracht hat.>\n\nUnser gemeinsamer Freund mehrere überzeugende Gründe aufgeführt, warum wir einander besser kennenlernen sollten.\n\nUnd ein Freund meiner Freunde ist auch immer mein Freund. Wendet Euch gerne jederzeit an mich, wenn ich Euch irgendwie behilflich sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[65131] = { id = 65131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Rendel und Knüppelfratze" }
quests[65132] = { id = 65132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Choofa", sourceObjective = "<Choofa bekommt große Augen, als er Euch sieht.>\n\n{name}! Endlich seid Ihr hier! Unser Freund konnte gar nicht mehr aufhören, von Euch zu schwärmen... was wohl auch daran lag, dass ich immer noch mehr Geschichten über Eure Abenteuer hören wollte.\n\nAber da Ihr nun hier seid, könnt Ihr mir die Geschichten ja auch selbst erzählen. Wir werden bestimmt im Handumdrehen beste Freunde!", sourceObjectiveStatus = "unverified-source-field" }
quests[65133] = { id = 65133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwung mit dem Drachen nutzen", description = "Und was, wenn sich Hindernisse im Weg befinden?\n\nWenn Ihr das Fliegen beherrscht, könnt Ihr Euren Schwung beibehalten und nach einem Sturzflug etwas Höhe gewinnen.\n\nWenn Ihr Euch dieses Mal in den Sturzflug begebt, führt Euch die Flugroute unterhalb des Landebereichs vorbei. Mit dem aufgenommenen Schwung könnt Ihr die verlorene Höhe am Ende des Kurses wiedergutmachen, um im Zielbereich zu landen.\n\nWenn Ihr irgendwo festhängt, benutzt die bronzene Taschenuhr. Celormu wird dann Eure Position zurücksetzen.", sourceObjective = "Taucht durch die Ringe und landet im Zielgebiet.", completion = "Gut gemacht. Der Rest ist nur eine Frage der Übung.", sourceObjectiveStatus = "unverified-source-field" }
quests[65134] = { id = 65134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Grufthüter Kassir" }
quests[65135] = { id = 65135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Dromanin Aliothe", sourceObjective = "<Dromanin Aliothe lächelt sanft.>\n\nIch war überrascht, als ich die genauen Details dieser Einladung gelesen habe. Allem Anschein nach haben wir einen gemeinsamen Freund, der mir über die Jahre sehr ans Herz gewachsen ist.\n\nEs freut mich, Euch hier zu sehen und fernab von meiner Höhle ein weiteres freundliches Gesicht anzutreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65136] = { id = 65136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Großmeister Vole", sourceObjective = "<Großmeister Vole mustert Euch mit einem schnellen Blick.>\n\nTja, seht Ihr, ich habe doch gleich gesagt, dass Ihr nicht SOOO stark sein würdet. Ich muss mal mit unserem Kumpel ein Wörtchen reden und klarstellen, dass ich recht hatte.\n\nVersteht mich nicht falsch, Ihr würdet im Kampf bestimmt immer noch eine gute Figur abgeben, aber um mich wirklich zu beeindrucken, müsstet Ihr mir schon noch ein bisschen mehr zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65137] = { id = 65137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Kleia und Pelagos", sourceObjective = "<Kleia begrüßt Euch herzlich.>\n\nNun, dieser Hof wird einfach immer besser.\n\nEs ist schön, Euch zu sehen, {name}. Unser gemeinsamer Freund hat mir Beeindruckendes über Eure Abenteuer erzählt. Ich freue mich schon darauf, mehr über Euch zu erfahren... und auch darüber, was Euch an Eurem Hof wichtig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[65138] = { id = 65138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Seuchenerfinder Marileth" }
quests[65140] = { id = 65140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Sika", sourceObjective = "<Sika streift Euch etwas Asche von der Schulter.>\n\nNicht persönlich nehmen. Asche fällt hier vom Himmel. Sehr unangenehm auf Kleidung. Sika hilft!\n\nSikas Freund erzählt Sika Geschichten über Euch. Guter Freund. Bester Freund! Vielleicht werdet Ihr auch bald bester Freund?", sourceObjectiveStatus = "unverified-source-field" }
quests[65141] = { id = 65141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund eines Freundes: Steinkopf", sourceObjective = "<Steinkopf streckt stolz die Brust raus.>\n\nMein bester Kumpel kennt Euch. Mein bester Kumpel ist bester Kumpel!\n\nAber bester Kumpel sagt, mehr als ein bester Kumpel möglich?\n\nWollt Ihr... auch bester Kumpel sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[65142] = { id = 65142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalparcours", description = "Als Hilfe für meine Studien habe ich über ein Netzwerk von Reiseportalen Überwachungsgeräte in ganz Zereth Mortis verteilt.\n\nMeine Geräte haben inzwischen eine beachtliche Menge an Forschungsdaten gesammelt. Nun wird es Zeit, all diese Daten auszuwerten.\n\nMit meinem Portalnetzwerk könnt Ihr zu all meinen Spüraugen reisen und die Daten einsammeln. Ich gebe Euch auch einen Portalinitiator, damit Ihr das Netzwerk wieder betreten könnt, wenn Ihr Euch mal verirrt!", sourceObjective = "Sammelt 12 Forschungsdaten von Spüraugen.", completion = "Ganz ausgezeichnet, aber es gibt noch so viel, das wir nicht verstehen. Aber mit meinen Spüraugen haben wir schon bald jede Menge neue Daten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65143] = { id = 65143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antros" }
quests[65145] = { id = 65145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikten auf der Spur", sourceObjective = "Die Forschung läuft sehr gut.\n\nVorläufige Ergebnisse haben mir Hinweise darauf gegeben, wie man mehr Relikte finden kann. Ich erzähle Euch davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[65146] = { id = 65146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktjäger", sourceObjective = "Manche Relikte scheinen Spuren zu hinterlassen oder einzigartige Merkmale zu besitzen.\n\nHier sind genauere Angaben dazu. So solltet Ihr noch mehr Relikte finden, wenn Ihr eine Quelle ausfindig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[65147] = { id = 65147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein gewöhnlicher Provost", sourceObjective = "Ihr seid zu Großem bestimmt, Schlundgänger. Das spüre ich!\n\nUnd der Oberste Schmied irrt sich nur selten.\n\nIhr strahlt eine Weisheit aus, die nur von großem Wissen kommt. Ja, das müsst ihr mit mir teilen!\n\n... Und umgekehrt natürlich auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[65149] = { id = 65149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiffren auf dem Prüfstand", description = "Es gibt eine Menge Konsolen wie diese in ganz Zereth Mortis.\n\nBisher hatte ich keine Ahnung, welche Funktion sie erfüllen, aber vielleicht will uns dieses Wesen ja genau das zeigen?\n\nZum Glück weiß ich, wo es noch weitere gibt. Ich markiere die Positionen auf Eurer Karte und begleite Euch... natürlich für die Forschung.\n\nDann wollen wir mal herausfinden, welchem Zweck dieses Wesen dient.", sourceObjective = "Findet die Konkordanzkonsolen in Zereth Mortis.", completion = "Ihr habt einen Einblick in unvorstellbares Wissen erhalten. Kommen wir nun dazu, wie es sich nutzen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65152] = { id = 65152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gestärkte Verbindung" }
quests[65157] = { id = 65157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gestärkte Verbindung", sourceObjective = "Von unserem geteilten Wissen wird ganz Maldraxxus profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65165] = { id = 65165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelische Unterstützung", sourceObjective = "Emenis Körper wurde zwar noch nicht wieder aufgebaut, aber sie kann Euch in Seelengestalt immer noch Rat und Unterstützung bieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[65168] = { id = 65168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Schwingen gehören Euch", sourceObjective = "Wir haben schon so viel zusammen durchgemacht, {name}. Ich bin Euch sehr dankbar für alles.\n\nAls Seelenbande könnten wir noch mehr schaffen! Was haltet Ihr davon?", sourceObjectiveStatus = "unverified-source-field" }
quests[65169] = { id = 65169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standhafter Verbündeter", sourceObjective = "Schlundgänger, es ist so weit.\n\nGeht das Band mit mir ein, dann erschüttern wir ganz Revendreth, bis es sich auf seine Wurzeln zurückbesinnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65170] = { id = 65170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenverwandtschaft", sourceObjective = "Dass unsere Seelen jetzt für immer miteinander verbunden sind, lässt mein Herz vor Freude springen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65177] = { id = 65177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenarbeit", description = "Wir wissen nie, wann aus der Verbindung von Schöpfung und Energie etwas vollkommen Neues entsteht.\n\nIn den Katalysatorgärten reift gerade eine Ernte völlig neuer Früchte. Ihre Samen könnten ganz besondere Eigenschaften aufweisen, und wir würden sie gern verstehen.\n\nSammelt bitte, was Ihr finden könnt, und sorgt dafür, dass die Gärten in Zukunft etwas sicherer sind.", sourceObjective = "Sammelt Katamelonensamen und vernichtet Überwucherungen in den Katalysatorgärten.", progress = "Wie soll man verstehen, was sich nicht definieren lässt?", completion = "Allein aus diesen kleinen Samen können wir so viel lernen. Was wird aus ihnen wachsen? Werden die Vombatas sie fressen?\n\nVielen Dank, dass Ihr mir geholfen habt, diesen Ort besser zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65218] = { id = 65218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navigation Playtest: Level Up (PART 1)", description = "Der Beginn des Azurblauen Gebirges." }
quests[65219] = { id = 65219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jiroische Taten", description = "Ich habe mit anderen Jiro gesprochen. Unsere Kugel kann ein Dämpfungsfeld erzeugen. Es sollte die Risse schließen und verhindern, dass sich neue Risse bilden.\n\nAber es muss dort getan werden, wo die Schlundmagie am stärksten ist. Zwischen den riesigen Ketten. Die Energie der Kugel wird Verschlinger anlocken. Ihr und ich müssen die Kugel verteidigen, bis das Feld steht.\n\nIch begleite die anderen. Kommt zum Riss, sobald Ihr bereit seid. Dort treffen wir uns.", sourceObjective = "Beschützt die Jiro vor den Verschlingern, bis das Dämpfungsfeld steht.", completion = "Die Verschlinger ziehen sich zurück. Für den Moment. Aber sie werden wiederkommen.\n\nEines Tages werden wir sie endgültig beseitigen. Bis dahin bleibe ich hier und beschütze die Jiro.\n\nOhne Euch wäre all dies unmöglich gewesen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[65220] = { id = 65220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navigation Playtest: Level Up (PART 2)", description = "Das Ende des Azurblauen Gebirges." }
quests[65226] = { id = 65226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flinken Fußes und furchtbar wählerisch", description = "Als die Schlundgebundenen nach Zereth Mortis gekommen sind, haben sie auch Schlundratten mitgebracht!\n\nEin Schwarm ihrer Schlundratten hat meine Höhle überrannt und eine Menge Dinge gestohlen, die ich für meine Forschung benötige!\n\nRana stellt ein Team zusammen, um alles zurückzuholen. Trefft Euch mit ihr und helft bei ihrem Plan.", sourceObjective = "Helft Rana, 6 gestohlene Relikte zurückzuholen und 80 diebische Schlundratten zu töten.", completion = "Ausgezeichnet! Ich hatte schon befürchtet, all diese Stücke wären für immer verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65230] = { id = 65230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bot-anik" }
quests[65231] = { id = 65231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplündertes Wissen" }
quests[65232] = { id = 65232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annelidenapokalypse" }
quests[65234] = { id = 65234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ach wie süß" }
quests[65237] = { id = 65237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orakel, heilt Euch selbst", description = "Das Gefäß, gerettet aus der Gefahr. Dieses Automa, ein tapferer Diener. Seine Energie, der Schlüssel zu meiner Genesung.\n\nPocopoc nennt es sich selbst. Dieser Name wird wieder sein.\n\nMein Name wird wieder mein. Saezurah, von den letzten Orakeln. Führende Hand der Retter von Zereth Mortis.\n\nBringt Pocopoc. Sein Dienst endet. Die Zeit ist gekommen, ich erwache.", sourceObjective = "Bringt Pocopoc zu Saezurah.", completion = "Nicht länger inaktiv. Das Muster fast vollkommen. Weitere Aufgaben warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65238] = { id = 65238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflochtene Seelen", description = "Ich gebe zu, zuerst war ich überzeugt, Pelagos würde ein furchtbares Opfer bringen. Aber jetzt sehe ich es. Er hat den Schattenlanden all die Hoffnung und das Mitgefühl geschenkt, die er in seinem Herzen trägt. Wir sollten nach ihm sehen.\n\nSprecht mit Tal-Inara, wenn Ihr Oribos erreicht.\n\nDort warte ich auf Euch, <mein Freund/meine Liebe>.", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Pelagos hat recht. Aber wenn jemand das schafft, was notwendig ist... Dann seid Ihr das. Davon bin ich fest überzeugt, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[65244] = { id = 65244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingbar" }
quests[65245] = { id = 65245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit der Schlingerei", description = "Einst... notwendig. Für das Gleichgewicht. Aber nun... verändert, verzerrt. Unharmonisch.\n\nEine Gefahr für das Muster. Inakzeptabel.\n\nAuslöschung, der einzige Weg.", sourceObjective = "Tötet mutierte Verschlinger in den Hallenden Gipfeln.", completion = "Der Entwurf muss wiederhergestellt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65249] = { id = 65249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Niederlage des Kerkermeisters", description = "Endlich haben wir die Pläne des Kerkermeisters vereitelt.\n\nSowohl die Schmiede der Nachleben als auch Azeroths Weltenseele sind wiederhergestellt, und die Schattenlande können sich nun endlich von der Animadürre erholen.\n\nIch weiß, es liegt in Eurer Natur, ständig nach neuen Zielen zu streben. Aber dies war ein monumentaler Sieg und er verdient einen kurzen Moment der Andacht.", sourceObjective = "Sprecht mit Bolvar, um den Sieg über den Kerkermeister erneut zu erleben.", completion = "Heute beginnt eine neue Ära für die Schattenlande.", sourceObjectiveStatus = "unverified-source-field" }
quests[65250] = { id = 65250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine interessante Gefangene", description = "Nachdem der Kerkermeister nun besiegt ist, müssen wir all die Wunden heilen, die er in den Schattenlanden hinterlassen hat. Und das beginnt mit Sylvanas Windläufer.\n\nAuch wenn unser Sieg ohne sie vielleicht unmöglich gewesen wäre, haben wir all ihre Gräueltaten weder vergessen noch vergeben. Sie muss sich dem Urteil des Richters in Oribos stellen.\n\nUther erwartet Euch im Ring der Schicksale. Zusammen werden wir Sylvanas zum Schmelztiegel geleiten.", sourceObjective = "Sprecht mit Uther in Oribos, um Sylvanas zum Richter zu geleiten.", completion = "Die Kunde von Sylvanas Ankunft hat sich wie ein Lauffeuer in den Schattenlanden verbreitet. Viele fordern, dass sie für ihre Verbrechen bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65252] = { id = 65252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stampfen im Akkord" }
quests[65255] = { id = 65255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erzwungene Kreislauf", description = "Zovaals Streitkräfte haben mit ihrem bösen Einfluss die Natur von Provis Fauna besudelt. So schnell, wie sich die Verderbnis ausbreitet, würde es zu lange dauern, alle einzeln zu läutern.\n\nStattdessen können wir ihre Energien einfach in die Systeme von Zereth Mortis zurückführen, damit neue Fauna entsteht. Nehmt diese Kugel und absorbiert im Augenblick des Todes ihre Energie. Sobald sie aufgeladen ist, läutert Ihr sie.", sourceObjective = "Ladet die Progenitorkugel auf und läutert sie anschließend.", completion = "Ihre Energie wird den Zyklus stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[65256] = { id = 65256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putt, putt, bumm", description = "Die einheimischen Puttriden von Zereth Mortis haben einen wirklich unschönen Schaden durch diese Eindringlinge erlitten.\n\nSetzt diesen Apparat gegen alle mit Fehlfunktion ein. Ansonsten könnten sie dem Land zu sehr schaden.", sourceObjective = "Verwendet den kinematischen Mikrolebensrekalibrator zur \"Rekalibrierung\" der fehlerhaften Puttriden im Großen Veld.", completion = "Diese Puttriden hinterlassen ziemlich viel Dreck. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65259] = { id = 65259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Mausoleums", description = "Kaum hatten wir das Reich des Todes betreten, warnte uns eine zurückgelassene Nachricht des Primus, dass der Kerkermeister das Mausoleum nicht erreichen darf.\n\nTrotz all unserer Anstrengungen ist es ihm dennoch gelungen.\n\nIm Herzen dieses uralten Orts ruhen Geheimnisse, mit denen der Kerkermeister den gesamten Kosmos beherrschen könnte. Gelingt es ihm, verlieren wir alles, was uns teuer ist.\n\nVersammelt Eure Verbündeten, {name}. Holt Euch den Sieg für die Schattenlande... und für Azeroth.", sourceObjective = "Besiegt den Kerkermeister im Mausoleum der Ersten.", completion = "Endlich ist unsere Kampagne zu Ende. Der Kerkermeister ist besiegt, dank Euch.\n\nIhr habt uns alle gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[65260] = { id = 65260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langer Marsch", description = "Der Richter erwartet uns. Der Zutritt zum Schmelztiegel ist zwar nur wenigen vergönnt, doch mehreren Azerothstämmigen wurde die Erlaubnis erteilt, Sylvanas' Verurteilung beizuwohnen.\n\nWir sind jedoch bei Weitem nicht die Einzigen, die von all dem Blutvergießen betroffen sind, das Sylvanas verursacht hat. Ihre Taten haben Schmerz und Leid über viele Seelen gebracht.\n\nDie Banshee selbst anzuschreien, während sie vorbeigeführt wird, ist womöglich ihre einzige Chance, ihren Unmut kundzugeben. Ihre Stimmen sollen erhört werden.", sourceObjective = "Sprecht mit Uther in Oribos, um Sylvanas zur Enklave zu eskortieren. Redet dann mit Tal-Inara, um zum Schmelztiegel gebracht zu werden.", completion = "Danke, dass Ihr gekommen seid, mein Freund.\n\nEs war mir wichtig, Euch hier zu haben, um diesen Augenblick miterleben zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65262] = { id = 65262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Vombatas" }
quests[65263] = { id = 65263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Sylvanas", description = "Die Zeit ist gekommen.\n\nBringen wir die dunkle Geschichte von Sylvanas Windläufer zu Ende und läuten wir ein neues Zeitalter für die Schattenlande ein.\n\nSprecht mich an, wenn wir beginnen können.", sourceObjective = "Sprecht mit Pelagos, um der Verurteilung von Sylvanas Windläufer beizuwohnen.", completion = "Wie soll ich zu Tyrandes Zufriedenheit urteilen, wenn sie und ihr Volk es waren, die durch die Bansheekönigin die größte Ungerechtigkeit erfahren haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[65264] = { id = 65264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Umsiedlung", description = "Verschlinger haben die nistenden Orniden in Provis Esper gestört.\n\nDas könnte unsere letzte Chance sein, sie zu untersuchen, bevor sie besudelt werden wie all die anderen.\n\nFangt mehrere Orniden in Provis Esper ein und bringt sie zu Pilger Arizh, damit er sie untersuchen und umsiedeln kann. Kümmert Euch um jedes Problem, das Euch dabei im Weg stehen mag.", sourceObjective = "Liefert 8 eingefangene wilde Protoorniden ab und tötet 6 seelenverdorrte Fresser und 2 Realitätsbrecher in Provis Esper.", completion = "Gut gemacht, {name}. Die Orniden werden an einen sichereren Ort gebracht, an dem wir sie beobachten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65265] = { id = 65265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrabene Relikte", description = "Vieles ging an die Invasoren verloren, jene, die mit Zerstörungswut in den Herzen kamen.\n\nWir können dieses Land nicht im Sinne der Ersten bewahren, wenn die Schlundgebundenen ungestört die letzten Überreste ihres Wissen pulverisieren.\n\nSchaut, was Ihr aus den Sanden von Provis Strata noch retten könnt.", sourceObjective = "Bergt seltsame Artefakte aus Provis Strata.", progress = "Was einst war, wird wieder sein.", completion = "Ohne den Kontext, in dem diese Objekte erschaffen wurden, werden sie für uns womöglich ein Rätsel bleiben. Wenigstens werden sie aber nicht mehr zertrampelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65266] = { id = 65266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Forschung", description = "Wir haben eine vielversprechende Quelle für korthianische Forschung entdeckt. Frühere Archivare haben Wissen in Speichern verborgen, die dann im Riss deponiert wurden.\n\nIch befürchte, dass diese Speicher nicht mehr sicher sind und die Schemen dieses Reichs sie verschlingen werden. Wir müssen diese Forschung unbedingt sichern, bevor sie für immer zerstört wird.\n\nVerwendet einen reparierten Rissschlüssel, um den Riss von Korthia zu betreten. Bergt die korthianischen Wissensspeicher.", sourceObjective = "Bergt korthianische Wissensspeicher aus dem Riss von Korthia für Archivar Roh-Suir.", progress = "Ohne Euch wäre das Archiv verloren, Schlundgänger.", completion = "Die in diesen Speichern enthaltene Forschung ist von unermesslichem Wert. Ich werde Euch eventuell bitten, in den Riss zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65267] = { id = 65267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rupft ihnen die Federn", description = "Diese seltsamen geflügelten Wesen haben mich neugierig gemacht und ich wollte mich ihnen mal vorstellen. Ich wäre gefressen worden, wenn nicht Professorin Hohnzirper und ihr großes mechanisches Federvieh gewesen wären!\n\nKönntet Ihr uns helfen, diesen \"Kreischerschwarm\" loszuwerden? Die einheimischen Blaufederrocs haben Probleme, ihre Nester vor ihnen zu verteidigen.\n\nUnd ich möchte nicht, dass weitere Bekanntschaften mit ihnen so verlaufen wie meine...", sourceObjective = "Tötet 8 Siecherinnen des Kreischerschwarms und 10 Bannklauen des Kreischerschwarms.", progress = "Ich muss den Harpyien trotz allem dafür danken, dass sie mir eine Chance gegeben haben, die Professorin zu treffen!", completion = "Ich danke Euch, {name}!\n\nIch habe der guten Professorin in Eurer Abwesenheit assistiert. Leider muss ich zugeben, dass es für sie schlimmer gemacht habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[65268] = { id = 65268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bzzzzt!", description = "Die Vespiden der Region nutzen die Trümmer dieser Gegend als Kernmaterial für ihre Nester. Normalerweise würden wir der Natur freien Lauf lassen, doch seit einiger Zeit holen sie sich auch einige der Relikte, die wir studieren.\n\nIch habe ein Gerät, mit dem es gelingen sollte, solche Relikte aus ihren Nestern zu entfernen, ohne die Kernstruktur zu beschädigten. Bergt die Relikte also mithilfe dieses Geräts.", sourceObjective = "Benutzt das Gerät der Erleuchteten Mittler, um die Progenitorrelikte aus den Vespidennestern zu entfernen.", completion = "Das reicht fürs Erste, danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[65269] = { id = 65269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Platzierung nach Plan", description = "Die Lage in den Katalysatorgärten ist beunruhigend.\n\nDie größte Sorge bereitet mir aber die Tatsache, dass wir nicht mehr wissen. Wenn es uns gelänge, die Ursache für die variierenden Energiemengen zu verstehen, die der Schöpfungskatalysator erzeugt, könnten wir besser über unser weiteres Vorgehen entscheiden.\n\nNehmt diese Sensoren. Platziert sie unter den Katalysatoren an den auf Eurer Karte markierten Stellen.", sourceObjective = "Platziert die Progenitormagiesensoren in den Katalysatorgärten.", completion = "Unsere klügsten Gelehrten werden die Sensordaten im Auge behalten. Wenn es die Ersten so wollen, werden sie uns den Weg weisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65271] = { id = 65271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbindungen schaffen", description = "Firim hat diese Erleuchteten Mittler nicht gerade im besten Licht dargestellt. Er wirkt allerdings auch etwas... exzentrisch.\n\nWie dem auch sei, wenn wir den Kontakt mit unseren Kameraden in Oribos wiederherstellen und den Kerkermeister besiegen wollen, werden wir in Zereth Mortis Verbündete brauchen.\n\nDie Schlundgebundenen scheinen sich vor den Toren der Zuflucht zu sammeln. Wir dürfen nicht zulassen, dass noch mehr Unschuldige der Niedertracht des Kerkermeisters zum Opfer fallen.\n\nHoffen wir, dass die Erleuchteten unsere Hilfe begrüßen werden. Nach Euch, <mein Freund/meine Liebe>.", sourceObjective = "Betretet die Zuflucht und trefft Euch mit den Erleuchteten.", progress = "Ihr wagt es, das heilige Land der Ersten zu betreten, Fremdling?", completion = "Wenn es nicht in Eurer Macht steht, uns zu helfen, dann müsst Ihr gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65274] = { id = 65274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navigation Playtest: Level Up" }
quests[65279] = { id = 65279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königlicher Erlass", description = "Bekloppte Gnolle Krone nicht verstehen, nur Gewalt. Macht sie fertig oder ich Euch fressen.", sourceObjective = "Tötet 8 Krieger von Brackenfell und 4 Schamanen von Brackenfell im Bachzahnbau.", completion = "Guter Anfang... aber ich Größeres vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65286] = { id = 65286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakonische Verbindungen", description = "Normalerweise würde ein solcher Flug wesentlich länger dauern. Aber wenn der bronzene Aspekt selbst Eure Reise beschleunigt, ist es möglich, die Strecke in Rekord...\n\n<ähm>...zeit zurückzulegen.\n\nOh, die Soldaten mit den spitzen Waffen? Kein Grund zur Sorge. Lediglich eine Formalität.\n\nIch werde Euch eine Audienz beim Lordkommandanten verschaffen, während Ihr und Azurathel Euch an die Arbeit macht.\n\nGlücklicherweise verfüge ich über beachtlichen Einfluss in dieser Stadt.", sourceObjective = "Betretet Sturmwind.", completion = "Vielleicht ist Furorions \"Einfluss\" nicht so beachtlich, wie er glaubt, wenn er so empfangen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[65287] = { id = 65287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eigelb trennen", description = "Ich habe die Schriftrolle entziffert und, Überraschung, es sind schlechte Nachrichten!\n\nDer Kreischerschwarm frisst die Blaufedern nicht nur, um sich zu ernähren. Vielmehr hat sich herausgestellt, dass sie einen oder zwei Zauber gefunden haben, die die angeborene Stärke der Rocs durch Verzehr auf sie übertragen. Das gilt insbesondere für die Eier!\n\nRettet unten an den Klippen so viele Roceier wie möglich. Das wird die Harpyien lange genug aufhalten, damit ich meinen Plan in die Tat umsetzen kann.\n\nUnd nehmt Euch vor umherwandernden Elementaren in Acht. Die Zauberei der Fluchweiber hat sie aufgescheucht!", sourceObjective = "Sammelt 20 Blaufedereier ein.", progress = "Die Rettung dieser Eier vor den Harpyien ist der Schlüssel zum Schutz der Blaufedern und darüber hinaus aller zukünftigen Beutetiere, die sie als Nächstes verschlingen wollten.", completion = "Ihr habt mehr geborgen, als ich mir hätte träumen lassen.\n\nVielleicht seid Ihr letztendlich doch gar nicht so übel. Nicht, als ob ich das gedacht hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[65297] = { id = 65297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sühne und Erneuerung", description = "Als ich der neue Richter wurde, fasste ich den festen Entschluss, jene anzuhören, die mich umgeben, und ihren Rat zu berücksichtigen, bevor ich ein ewiges Urteil fälle.\n\nIch ahne, was Tyrande für Sylvanas im Sinn hat. Ihre Wut wird durch Weisheit gemäßigt, und ich vertraue auf ihre Entscheidung.\n\nTrefft sie im Ring der Übertragung und seht zu, wie sich ihr Urteil erfüllt.", sourceObjective = "Sprecht mit Tyrande im Ring der Übertragung in Oribos.", completion = "Gerechtigkeit für Teldrassil. Frieden für die Kaldorei.", sourceObjectiveStatus = "unverified-source-field" }
quests[65302] = { id = 65302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zum Königreich", description = "Brauche Waffen für Plan. Hab gute Waffen, sind aber eingeschlossen. Gnolle Schlüssel in Lager gelassen haben, in beschütztem Waffendepot.\n\nHolt spitzigste Stöcke. Gibt meiste Blutflecken.", sourceObjective = "Beschafft den Schlüssel und öffnet damit das Waffendepot.", progress = "Ihr die Waffen bringen oder ich Euch fressen soll?", completion = "Wollte immer Machtstab haben!\n\nMOHN-ARCH GIBT!", sourceObjectiveStatus = "unverified-source-field" }
quests[65305] = { id = 65305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das weitere Vorgehen", description = "Wie ich sehe, habt Ihr einen neuen Freund, <Schlundgänger/Schlundgängerin>!\n\nIch frage mich, was Ihr mit Pocopoc an Eurer Seite wohl als Nächstes über Zereth Mortis herausfinden werdet. Die Geheimnisse, die wir hier lüften, werden uns im Kampf gegen den Kerkermeister eine große Hilfe sein. Vielleicht zeigen sie uns sogar, wie man dieses Orakel weckt.\n\nHochlord Bolvar wird gewiss davon erfahren wollen.\n\nBitte begebt Euch in die Zuflucht und bringt ihn auf den neuesten Stand. Gleich draußen vor der Höhle ist ein Transportmittel, das Ihr nutzen könnt.\n\nIch werde hierbleiben und über das Orakel wachen.", sourceObjective = "Kehrt zu Hochlord Bolvar Fordragon in die Zuflucht zurück.", completion = "Ihr seid zurückgekehrt, Schlundgänger. Welche Neuigkeiten habt Ihr für mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[65306] = { id = 65306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fäulnisfarmer", description = "Verfall. Eklig, stinkt und tut weh. Hab Idee, aber brauche Schleim. IHR SCHLEIM HOLEN!", sourceObjective = "Sammelt 20 Portionen müffelnden Schleim von verrottenden Wurzeln.", progress = "BRAUCHE MEHR SCHLEIM!", completion = "Weiches Zehenzeug. Sehr toll.", sourceObjectiveStatus = "unverified-source-field" }
quests[65307] = { id = 65307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade zuerst", description = "Das Gift im Hort hat uns fast alle dahingerafft. Während das Gegengift zubereitet wird, müsst Ihr die Verwundeten suchen und sie heilen.\n\nJa, sogar die blauen Drakoniden. Die Heilschwingen stehen nicht untätig herum, während andere leiden.", sourceObjective = "Heilt verletzte Dracthyr und Drakoniden.", progress = "Die durch den Hort wabernden Gifte konnten den Stasiszauber nicht durchdringen, aber sie erfassten uns, als wir erwachten.", completion = "Gewalt ist nicht der einzige Weg zum Sieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[65313] = { id = 65313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appetit auf Geflügel", description = "Segallia scheint in Ordnung zu sein, sie kann gut mit Geräten umgehen, aber sie gerät leicht in Panik.\n\nEin Beispiel: Als ich sie in die Höhlen direkt südlich von hier geschickt habe, wurde sie prompt von einer ungewöhnlich großen Harpyie dort hinausgejagt. Anscheinend folgten auch die anderen ihren Befehlen.\n\nKönnte sie die Matriarchin dieser Brut sein? Vielleicht eine Art Kommandantin? Geht rein und findet es heraus, {name}.\n\nUnd scheut Euch nicht, ein paar Federn auszurupfen, wenn Ihr wisst, was ich meine.", sourceObjective = "Tötet Hawthia Rocfresser.", completion = "Meine hochempfindlichen Vogelsinne sagen mir, dass dieser Kreischerschwarm nicht nur zum Fressen hier ist...\n\nDas habt Ihr gut gemacht, {name}. Jetzt lasst mich diese Schriftrolle entziffern, damit wir herausfinden, auf was die Harpyien es abgesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[65324] = { id = 65324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschachtelte Muster", description = "Wir stehen am Ursprung der Schattenlande. Wir dürfen nicht zulassen, dass dieser Ort sie ins Verderben reißt.\n\nArbeitet mit unseren neuen Verbündeten zusammen, {name}. Ihre Unterstützung wird den Unterschied zwischen unserem Erfolg und dem Untergang aller Dinge ausmachen.", sourceObjective = "Unterstützt Eure Verbündeten in Zereth Mortis, indem Ihr Weltquests und tägliche Quests abschließt, Schätze plündert und seltene Kreaturen tötet.", completion = "Wir kommen unserem Ziel näher. Schritt um Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65325] = { id = 65325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partikel des Wissens", description = "Die Kreaturen des Ungezähmten Grüns vertilgen alles in Sichtweite. Sie haben unseren Kompilationsknoten verschlungen, und auch die Kompositionspartikel, die für die Kompilation benötigt werden. Wir Jiro brauchen diese Ressourcen.\n\nDieses Gebiet ist zu gefährlich für ungeschützte Jiro.\n\nBitte helft uns, unsere Ressourcen zurückzugewinnen. Mai Obet wird Euch unterstützen.", sourceObjective = "Bergt 1 Kompilationsknoten und 10 Kompositionspartikel.", progress = "Habt Ihr unsere Ressourcen geborgen?", completion = "Ihr habt unsere Ressourcen wiederbeschafft. Wir wissen Eure Unterstützung zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65326] = { id = 65326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wartung unter erschwerten Bedingungen", description = "Automas benötigen Unterstützung für einen ordnungsgemäßen Betrieb. Das ist unsere Aufgabe, aber Fremde haben zu viele Störungen verursacht. Die können wir nicht alle beheben.\n\nBitte helft Mai Obet dabei, die Leistung der Automas zu untersuchen und einzuschätzen.", sourceObjective = "Untersucht 10 Automakonstruktoren in Provis Flora.", completion = "Die Automas funktionieren wie vorgesehen. Danke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[65327] = { id = 65327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Ambystidenflitzer", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65328] = { id = 65328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein werdender Richter", description = "<Schlundgänger/Schlundgängerin>, ich... ich weiß nicht, was ich sagen soll. Damit habe ich nicht gerechnet.\n\nSie hat von Vorbereitungen und einem neuen Richter gesprochen. Davon müssen wir unseren Freunden in der Zuflucht erzählen.", sourceObjective = "Geht zur Zuflucht und überbringt die Neuigkeiten, dass Saezurah nach einem neuen Richter sucht.", completion = "Ein Richter? Ich hätte nicht gedacht, dass wir das in Ordnung bringen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[65329] = { id = 65329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Zuflucht", description = "Lasst uns nach Zereth Mortis zurückkehren. Ihr solltet mit Bolvar sprechen und ihm berichten, was wir erreicht haben. Diesen Sieg haben wir errungen, aber es gibt noch viel zu tun.", sourceObjective = "Meldet Euch bei Bolvar in der Zuflucht.", completion = "Ein neuer Richter wurde eingesetzt? Hervorragende Nachrichten, {name}, und ein wichtiger Schritt, um das Gleichgewicht der Schattenlande wiederherzustellen. Eure Anstrengungen hier werden nicht vergessen.\n\nDas ist jedoch nur ein Schritt auf unser Ziel hin. Wir müssen unsere Position in Zereth Mortis weiter stärken und die Streitkräfte des Kerkermeisters vertreiben.\n\nUnsere Arbeit geht weiter, aber mit Euch an unserer Seite ist der Sieg ein gutes Stück näher. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[65331] = { id = 65331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzliche Heilmittel", description = "Mithilfe der von Euch gesammelten Wurzeln habe ich ein Gemisch hergestellt, das die Pflanzen theoretisch in ihren natürlichen Zustand zurückversetzen sollte.\n\nSchleudert Phiolen mit dem Heilmittel auf Peitscher in den Katalysatorgärten.\n\nSollte es funktionieren, wunderbar! Falls nicht, müsst Ihr Euch ein wenig direkter darum kümmern, indem Ihr sie tötet.", sourceObjective = "Tötet 30 intelligente Überwucherungen und 6 fleischfressende Überwucherungen.", completion = "Ein mehr oder weniger erfolgreicher Testlauf, aber immerhin ein Erfolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[65332] = { id = 65332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Wilder Skarabid", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65333] = { id = 65333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Multihuhn", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65334] = { id = 65334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Aggressiver Puttrid", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65335] = { id = 65335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten aus Oribos", description = "Ich habe wichtige Neuigkeiten, die uns Aufschluss über die Methoden des Kerkermeisters geben sollten.\n\nGlaube und Erkenntnis könnten uns zu wahrer Gerechtigkeit führen.\n\nWir haben viel zu besprechen, <Held/Heldin>.", sourceObjective = "Sprecht mit Uther dem Lichtbringer.", completion = "Sylvanas' Erfahrung könnte ein immanenter Teil von Anduins Schicksal sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[65336] = { id = 65336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Stabilisierter Geomentar", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65348] = { id = 65348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Omnipotenzialkern", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65349] = { id = 65349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Huld", description = "Das Wasser der Quelle fließt nicht mehr.\n\nDie Entwürfe der Ersten haben noch nie versagt. Die Pilger beginnen, sich zu fragen... ob die Ersten verärgert sind.\n\nSelbstverständlich dürfen sie es hinterfragen, aber MEIN Glaube ist unerschütterlich. Und wie erwartet, haben uns die Ersten eine Lösung geschickt.\n\nEuch natürlich.\n\nUralte Forschung und Schriften legen nahe, dass der Ursprung der Quelle in einem unterirdischen Tempel in Provis Esper liegt. Geht. Ich vertraue darauf, dass Ihr die Quelle wiederherstellen werdet.", sourceObjective = "Begebt Euch nach Provis Esper.", completion = "<Dieses Automa wurde von Verschlingern verheert. Seine Hand umklammert ein merkwürdiges Objekt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65350] = { id = 65350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fluss wiederherstellen", description = "Seht! Verschlinger haben die Verteidigung des Tempels durchdrungen. Diese gefräßigen Biester ernähren sich von jeglicher Energie, die sie finden können. Sie müssen von der Macht der Quelle angezogen worden sein.\n\nKein Wunder, dass das Wasser nicht mehr fließt!\n\nDie Lösung muss im Inneren der Lokrischen Esper liegen. Versucht, etwaige Schäden zu beheben, wenn Ihr dort seid.", sourceObjective = "Findet einen Weg, die Lokrische Esper wiederherzustellen.", progress = "<Die Konsole summt vor Macht.>", completion = "<Eure Bemühungen waren von Erfolg gekrönt. Das Wasser fließt wieder durch den Tempel. Die Quelle ist wiederhergestellt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65351] = { id = 65351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Resonantes Echo", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[65353] = { id = 65353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Automa-freie Kost", description = "Diese Verschlinger sind gnadenlos! Sie ernähren sich von jeglicher Energie, die sie finden können. Hält man sie nicht auf, verschlingen sie sicherlich noch ganz Zereth Mortis. Wir können nicht zulassen, dass die Schöpfungen der Ersten durch diese Eindringlinge besudelt werden!\n\nIch bin kein Kämpfer. Aber Ihr... Vielleicht haben die Ersten Euch doch zu uns geschickt. Werdet Ihr helfen?", sourceObjective = "Tötet 10 einfallende Fresser und Realitätsbrecher.", completion = "Fremder, ich... ich entschuldige mich. Ich hatte kein Vertrauen in Euch. Und so kam auch mein Glaube ins Wanken. Vergebt mir und nehmt meinen Dank an. Die Ersten führen wahrlich Eure Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[65354] = { id = 65354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Protoprickler", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "<Die Protoformschmiede stimmt ein melancholisches Lied an, während sie den Bauplan assimiliert.>", sourceObjectiveStatus = "unverified-source-field" }
