quests[65362] = { id = 65362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unproduktiv", description = "Feinde von Zereth Mortis verkleiden sich als produktive Automas. Allerdings schließen sie keine ihrer übertragenen Aufgaben ab.\n\nScannt die Automas, um die feindlichen Bedrohungen zu offenbaren, und vernichtet sie dann.\n\nMai Obet wird dabei helfen.", sourceObjective = "Tötet 6 Schreckenslordinfiltratoren.", completion = "Ihr habt die Erwartungen übertroffen. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65363] = { id = 65363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlicher Zustand", description = "Feinde haben die Jiro angegriffen und sie vom Kreis abgetrennt. Die Jiro sind nicht länger stabil. Sie sind eine Gefahr für die Ordnung der Dinge.\n\nSie müssen entfernt werden.", sourceObjective = "Tötet Leinenhüter Helzid und 12 beherrschte Jiro.", progress = "Habt Ihr Euch um die Bedrohung gekümmert?", completion = "Die Ordnung konnte wiederhergestellt werden. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65364] = { id = 65364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superjiro", description = "Die Fremdlinge haben die Aufgaben und den Zweck der Jiro gestört. Wir können nicht zulassen, dass sich dies fortsetzt.\n\nWir werden eine größere Jiro ermächtigen, die dabei hilft, sich dieser Bedrohung zu stellen. Die Erste Jiro wird die Feinde vernichten, die Zereth Mortis bedrohen.\n\nHelft dabei, die Erste Jiro zu steuern, um unsere Krise zu beenden.", sourceObjective = "Steuert die Erste Jiro, um 7 verstörte Jiro zu retten, während Ihr 5 schlundgebrochene Automas und 100 Streitkräfte der Schlundgebundenen niederstreckt.", completion = "Die Ordnung konnte wiederhergestellt werden. Wir danken Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[65370] = { id = 65370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauchgefühl", description = "Ein Crescendium ist ein mächtiges Werkzeug, das die Automas erschaffen haben. So ein Crescendium wird den Jiro als Hilfe gewährt, wenn die Arbeit schwer oder wichtig ist. Als die Verschlinger angriffen, haben sie Crescendien vermutlich als... Futter betrachtet.\n\nCrescendien sind robust. Sie gehen nicht so schnell kaputt. Seht in die Mägen von größeren Verschlingern nach. Vielleicht findet Ihr noch eins, das intakt ist?", sourceObjective = "Beschafft ein Crescendium von einem unersättlichen Brecher oder einem gierigen Pirscher auf der Terrasse der Formgebung.", progress = "Wir haben nur sehr wenige Crescendien. Es ist wichtig, eins davon zu beschaffen.", completion = "<Der Jiro blickt auf den mit Gedärmen bedeckten Apparat.>\n\nNicht ideal. Aber zum größten Teil intakt.... Es müsste ein wenig gesäubert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[65371] = { id = 65371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eigenes Nest", description = "Die Schriftrolle, die Ihr gefunden habt, ist ein Befehl, alle Blaufedereier zur Harpyienköchin Fritt-Erie zu bringen. Offenbar isst die Matriarchin des Kreischerschwarms nichts, was nicht ordentlich zubereitet und gewürzt wurde.\n\nAlso werden wir ihr ein besonderes Ei kredenzen. Eines, das EXPLOSIV lecker ist... und explodiert, wenn sie es isst... versteht sich.\n\nUnd wie werdet Ihr es ihr überbringen? In Verkleidung!\n\nTötet die Biester auf den unteren Klippen, sammelt die Teile auf dieser Liste ein, und ich fertige Euch ein Kostüm mit Federn und allem Drum und Dran.", sourceObjective = "Sammelt 20 Kreischerschwarmkrallen, 6 Kreischerschwarmstäbe und 3 Flussbrutkerne.", progress = "Habt Ihr schon, wonach ich gefragt hatte?", completion = "Perfekt! Und ein wenig eklig. Ganz nach Plan.\n\nZeit, eine Verkleidung zu basteln und dieser Matriarchin die Federn zu rupfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[65373] = { id = 65373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auseinandergerupft", description = "Oh, nein... Ich habe einen gewaltigen Fehler gemacht.\n\nHarleen hat mir den berühmten Federrupfer 3300 anvertraut, eine phänomenale Erfindung von ihr persönlich!\n\nIch wollte in der Höhle südlich von hier Rocfedern für ihre Forschungsarbeit rupfen, aber die Harpyien haben mir aufgelauert und er zerbrach in mehrere Teile, als ich hinauslief.\n\nBitte sammelt die Teile ein! Sie liegen wahrscheinlich wie abgeworfene Schuppen überall auf dem Höhlenboden verstreut.\n\nIch kann ihn bestimmt wieder zusammensetzen. Kein Zweifel. Nun, wahrscheinlich.", sourceObjective = "Bergt 4 Teile des Federrupfers 3300.", progress = "Ich wollte mich unbedingt beweisen!", completion = "Oh, den Schwärmen sei Dank!\n\nDie Professorin ist mir mittlerweile sehr sympathisch und das hätte das Ende unserer neuen Freundschaft sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[65374] = { id = 65374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Rupfen", description = "Harleen hat mir erzählt, dass sie eine Verkleidung für Euch anfertigt! Wie aufregend! Aber sie braucht noch ein paar Federn von Rocküken, um das Kostüm zu vervollständigen.\n\nGlücklicherweise habe ich gerade die Reparatur des Federrupfers 3300 abgeschlossen!\n\nDer Kreischerschwarm fängt auf den unteren Klippen Rocküken ein, um sie aufzuziehen und für sich selbst zu züchten. Benutzt den Rupfer, um die Küken aus der Gefahr zu befreien. Er rupft auch automatisch einige ihrer Federn für Euch!\n\nZwei Fliegen mit einem Rupfer, würde ich sagen!", sourceObjective = "Rupft 6 Kükenfedern aus.", progress = "Professorin Hohnzirper meint, ich hätte ein Händchen für technische Spielereien! Wenn ich nicht zum Militär der Dracthyr gehören würde, könnte ich dann wohl in einer Goblinstadt arbeiten?", completion = "Das sind mehr als genug Federn! Und alle wurden gesammelt, ohne dass der Federrupfer explodiert ist... oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[65375] = { id = 65375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplanreassimilierung: Blasser majestätischer Cervid", description = "<Dieser Bauplan enthält das Muster eines neuen Protoformkonstrukts. Präsentiert ihn an einer geeigneten Protoformschmiede, dann wird sie vielleicht eine dieser Kreaturen für Euch instanziieren.>\n\n<Die Erleuchteten der Huld des Pilgers wissen gewiss, wo sich eine solche Schmiede befindet.>", sourceObjective = "Präsentiert den Bauplan an einer geeigneten Protoformschmiede.\n\nBereitgestellter Gegenstand:", completion = "Exzellent. Mit diesem Bauplan und den richtigen Komponenten kann hier ein neues Lied beginnen, das Euch begleitet.", sourceObjectiveStatus = "unverified-source-field" }
